"""Review & training layer: turn an edit into a list of decisions the creator can approve / swap / remove / comment on.

    projects/<slug>/review/decisions.json   the creator's answers for THIS episode (stable keys, survive rebuilds)
    projects/<slug>/review/scenes.json      story beats written by a custom builder (optional): [{id,note,segs:[ids]}]
    studio/learning/feedback.jsonl          every decision + comment + context, appended forever (training data)
    studio/learning/prefs.json              per-asset / per-template preference score the finder uses (assets.find)
    studio/learning/notes.md                the creator's free-text comments, grouped, for the next editing pass

Used by server.py (/api/projects/<slug>/review*) and by builders (`apply_decisions(edl, slug)` re-applies the answers after
every rebuild, `removed_scenes(slug)` lists beats the creator cut).

CLI:  uv run python -m mcstudio.review md <slug>      writes projects/<slug>/REVIEW.md
"""
from __future__ import annotations

import json
import re
import sys
import time
from pathlib import Path

from . import assets as A
from .edl import EDLError, build_spans, resolve_time, seg_duration, validate
from .paths import PROJECTS, STUDIO

LEARN = STUDIO / "learning"
SFX_KINDS = ("sfx",)
ASSET_KINDS = ("sfx", "meme", "greenscreen", "image", "music")


# ------------------------------------------------------------------ small io helpers
def _read(p: Path, default=None):
    try:
        return json.loads(Path(p).read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return default


def _write(p: Path, data) -> None:
    p = Path(p)
    p.parent.mkdir(parents=True, exist_ok=True)
    tmp = p.with_name(p.name + ".tmp")
    tmp.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")
    tmp.replace(p)


def review_dir(slug: str) -> Path:
    return PROJECTS / slug / "review"


def load_decisions(slug: str) -> dict:
    d = _read(review_dir(slug) / "decisions.json", {}) or {}
    d.setdefault("items", {})
    d.setdefault("additions", [])
    d.setdefault("general", "")
    return d


def save_decisions(slug: str, d: dict) -> None:
    d["updated"] = time.strftime("%Y-%m-%d %H:%M:%S")
    _write(review_dir(slug) / "decisions.json", d)


def removed_scenes(slug: str) -> set[str]:
    """Story beats (by note) the creator cut; custom builders skip them on the next rebuild."""
    return {k.split("|", 1)[1] for k, v in load_decisions(slug)["items"].items()
            if k.startswith("scene|") and v.get("status") == "remove"}


# ------------------------------------------------------------------ context helpers
def _words(slug: str) -> list[dict]:
    tr = _read(PROJECTS / slug / "work" / "transcript.json", {"segments": []}) or {"segments": []}
    return [w for s in tr.get("segments", []) for w in s.get("words", [])]


def _context(words: list[dict], src: float | None, before=2.5, after=3.5, cap=16) -> str:
    if src is None or not words:
        return ""
    ws = [w["word"].strip() for w in words if src - before <= w["start"] <= src + after]
    return " ".join(ws[:cap])


def _moments_from_text(text: str) -> list[str]:
    try:
        from .autoplan import LEXICON
    except Exception:  # noqa: BLE001
        return []
    t = re.sub(r"[^\w' ?!]", "", text.lower())
    out: list[str] = []
    for rx, moment, _score, _tmpl in LEXICON:
        if re.search(rx, t) and moment not in out:
            out.append(moment)
    return out[:3]


def _lookup(i):
    try:
        return A.get(i)
    except KeyError:
        return None


def _asset_brief(a: dict | None) -> dict | None:
    if not a:
        return None
    return {k: a.get(k) for k in ("id", "title", "category", "kind", "duration_s", "thumb", "root", "path", "moments",
                                  "roles", "description", "peak_s", "content_rating", "key_mode", "favorite",
                                  "copyright_risk", "notes")}


# ------------------------------------------------------------------ build the review items from edit.json
def build_items(slug: str) -> dict:
    p = PROJECTS / slug
    edl = _read(p / "edit.json")
    if not edl:
        return {"items": [], "duration": 0, "warnings": ["no edit.json yet"]}
    warnings: list[str] = []
    try:
        validate(edl)
        spans = build_spans(edl, _lookup)
    except (EDLError, KeyError, TypeError) as e:
        return {"items": [], "duration": 0, "warnings": [f"EDL error: {e}"]}
    words = _words(slug)
    segs = edl["segments"]
    seg_t: dict[str, tuple[float, float, dict]] = {}
    t = 0.0
    for i, s in enumerate(segs):
        d = seg_duration(s, _lookup)
        seg_t[s.get("id") or f"seg{i}"] = (t, t + d, s)
        t += d
    total = t

    def src_at_out(ot: float) -> float | None:
        for st, en, s in seg_t.values():
            if s.get("type", "source") == "source" and st - 1e-6 <= ot <= en + 1e-6:
                return s["in"] + (ot - st) * s.get("speed", 1.0)
        return None

    def src_of(ev: dict, at: float) -> float | None:
        if "src_at" in ev:
            return ev["src_at"]
        if ev.get("seg") in seg_t and "rel" in ev:
            s = seg_t[ev["seg"]][2]
            return s.get("in", 0) + ev["rel"] * s.get("speed", 1.0) if s.get("type", "source") == "source" else None
        return src_at_out(at)

    items: list[dict] = []
    seen: dict[str, int] = {}

    def add(kind, ev_ref, start, end, key_core, title, current, src, asset_id=None):
        n = seen.get(key_core, 0)
        seen[key_core] = n + 1
        key = key_core if n == 0 else f"{key_core}#{n}"
        ctx = _context(words, src)
        items.append({"key": key, "kind": kind, "ref": ev_ref, "start": round(start, 2), "end": round(max(end, start + 0.4), 2),
                      "title": title, "current": current, "src": None if src is None else round(src, 2), "context": ctx,
                      "moments": _moments_from_text(ctx), "asset": asset_id})

    def anchor(ev, at, src):
        return f"{round(src, 1)}" if src is not None else f"o{round(at, 1)}"

    # --- audio: sfx
    for k, ev in enumerate(edl.get("audio", {}).get("sfx", [])):
        if not ev.get("asset"):
            continue                                                  # pre-mixed montage hit tracks etc.
        at = resolve_time(ev, spans, warnings, f"sfx[{k}]") if ("at" in ev or "src_at" in ev or "seg" in ev) else None
        if at is None:
            continue
        a = _lookup(ev["asset"])
        dur = ev.get("dur") or (a or {}).get("tail_s") or (a or {}).get("duration_s") or 1.0
        src = src_of(ev, at)
        add("sfx", ["audio.sfx", k], at, at + dur, f"sfx|{ev['asset']}|{anchor(ev, at, src)}", (a or {}).get("title") or ev["asset"],
            {"asset": ev["asset"]}, src, ev["asset"])
    # --- overlays
    for k, ev in enumerate(edl.get("overlays", [])):
        at = resolve_time(ev, spans, warnings, f"overlay[{k}]") if ("at" in ev or "src_at" in ev or "seg" in ev) else None
        if at is None:
            continue
        src = src_of(ev, at)
        dur = ev.get("dur") or 2.0
        typ = ev.get("type")
        if ev.get("cinematic"):
            add("cinematic", ["overlays", k], at, at + dur, f"cin|{ev.get('cinematic')}", f"Flashback shot: {ev.get('cinematic')}",
                {"file": ev.get("file")}, src)
        elif typ == "greenscreen":
            a = _lookup(ev.get("asset", ""))
            add("greenscreen", ["overlays", k], at, at + dur, f"gs|{ev.get('asset')}|{anchor(ev, at, src)}", (a or {}).get("title") or ev.get("asset"),
                {"asset": ev.get("asset")}, src, ev.get("asset"))
        elif typ == "motion":
            tpl = ev.get("template") or ev.get("file")
            add("motion", ["overlays", k], at, at + dur, f"mo|{tpl}|{anchor(ev, at, src)}", f"Graphic: {tpl}",
                {"template": ev.get("template"), "vars": ev.get("vars") or {}}, src)
        elif typ in ("image", "video"):
            a = _lookup(ev.get("asset", "")) if ev.get("asset") else None
            add("image", ["overlays", k], at, at + dur, f"img|{ev.get('asset') or ev.get('file')}|{anchor(ev, at, src)}",
                (a or {}).get("title") or ev.get("file") or ev.get("asset"), {"asset": ev.get("asset")}, src, ev.get("asset"))
    # --- text pops
    for k, ev in enumerate(edl.get("text", [])):
        at = resolve_time(ev, spans, warnings, f"text[{k}]") if ("at" in ev or "src_at" in ev or "seg" in ev) else None
        if at is None:
            continue
        src = src_of(ev, at)
        add("text", ["text", k], at, at + (ev.get("dur") or 1.2), f"tx|{ev.get('text', '')[:24]}|{anchor(ev, at, src)}",
            f"Text: {ev.get('text', '')}", {"text": ev.get("text"), "style": ev.get("style", "impact")}, src)
    # --- meme cutaways (segments of type cutaway)
    for i, s in enumerate(segs):
        if s.get("type") != "cutaway":
            continue
        st, en, _ = seg_t[s.get("id") or f"seg{i}"]
        prev = next((x for x in reversed(segs[:i]) if x.get("type", "source") == "source"), None)
        src = prev["out"] if prev else None
        a = _lookup(s.get("asset", ""))
        add("meme", ["segments", i], st, en, f"meme|{s.get('asset')}|{anchor(s, st, src)}", (a or {}).get("title") or s.get("asset"),
            {"asset": s.get("asset")}, src, s.get("asset"))
    # --- music beds
    for k, ev in enumerate(edl.get("audio", {}).get("music", [])):
        at = ev.get("at", 0.0)
        a = _lookup(ev.get("asset", ""))
        add("music", ["audio.music", k], at, ev.get("until", total), f"music|{ev.get('asset')}|{int(at // 15)}",
            f"Music: {(a or {}).get('title') or ev.get('asset')}", {"asset": ev.get("asset")}, src_at_out(at + 3), ev.get("asset"))
    # --- bleeps
    for k, ev in enumerate(edl.get("audio", {}).get("bleeps", [])):
        at = resolve_time(ev, spans, warnings, f"bleep[{k}]") if ("at" in ev or "src_at" in ev) else None
        if at is None:
            continue
        add("bleep", ["audio.bleeps", k], at, at + (ev.get("dur") or 0.4), f"bleep|{round(ev.get('src_at', at), 1)}", "Bleep (swear covered)",
            {}, ev.get("src_at"))
    # --- story beats written by a custom builder
    scenes = _read(review_dir(slug) / "scenes.json", []) or []
    for sc in scenes:
        ids = [i for i in sc.get("segs", []) if i in seg_t]
        if not ids:
            continue
        st = min(seg_t[i][0] for i in ids)
        en = max(seg_t[i][1] for i in ids)
        add("scene", ["scene", sc["note"]], st, en, f"scene|{sc['note']}", f"Scene: {sc['note']}",
            {"note": sc["note"], "act": sc.get("act")}, src_at_out(st + 1), None)
    # --- additions the creator made in the review page
    dec = load_decisions(slug)
    for n, ad in enumerate(dec["additions"]):
        add("added", ["addition", n], ad["out_time"], ad["out_time"] + 2.0, f"add|{n}", f"Added {ad['kind']}: {ad.get('label') or ''}",
            {k: v for k, v in ad.items() if k not in ("comment",)}, src_at_out(ad["out_time"]), ad.get("asset"))
    items.sort(key=lambda x: (x["start"], x["kind"]))
    return {"items": items, "duration": round(total, 2), "warnings": warnings[:20]}


# ------------------------------------------------------------------ recommendations
def options(slug: str, key: str, q: str = "", limit: int = 8) -> list[dict]:
    """Recommended alternatives for one review item (the same finder/scorer the planner uses)."""
    items = {i["key"]: i for i in build_items(slug)["items"]}
    it = items.get(key)
    if not it:
        return []
    kind = it["kind"]
    cats = {"sfx": ["sfx_meme", "sfx_ui", "sfx_minecraft", "sfx_mlg", "sfx_laugh"], "meme": ["meme_video"],
            "greenscreen": ["green_screen"], "image": ["image", "brand_sticker"], "music": ["music", "sfx_meme"],
            "added": []}.get(kind, [])
    cur = _lookup(it.get("asset") or "") if it.get("asset") else None
    if kind == "added":
        k2 = (it["current"] or {}).get("kind")
        cats = {"sfx": ["sfx_meme", "sfx_ui", "sfx_minecraft", "sfx_mlg"], "meme": ["meme_video"], "greenscreen": ["green_screen"]}.get(k2, [])
    if not cats:
        return []
    moments = list(dict.fromkeys(it.get("moments", []) + ((cur or {}).get("moments") or [])[:2]))[:4] or ["emphasis"]
    roles = ((cur or {}).get("roles") or [])[:1] if kind == "sfx" else []
    res = A.find(A.Query(moments=moments, roles=roles, categories=cats, text=q or None, project=slug, limit=limit + 4,
                         max_rating="mild", max_duration=(12 if kind != "music" else None),
                         min_duration=(60 if kind == "music" else None)))
    out = []
    for r in res:
        if r["id"] == it.get("asset"):
            continue
        out.append(_asset_brief(r))
        if len(out) >= limit:
            break
    return out


# ------------------------------------------------------------------ learning log + preferences
def _prefs() -> dict:
    return _read(LEARN / "prefs.json", {}) or {}


def asset_pref(asset_id: str) -> float:
    """Preference score for the finder (assets.find adds 0.35 * this, clamped)."""
    return float(_prefs().get(asset_id, 0.0))


def _bump(prefs: dict, key: str | None, delta: float) -> None:
    if key:
        prefs[key] = round(max(-4.0, min(4.0, prefs.get(key, 0.0) + delta)), 2)


def record_decision(slug: str, key: str, status: str, choice: dict | None, comment: str, item: dict | None) -> dict:
    d = load_decisions(slug)
    prev = d["items"].get(key, {})
    d["items"][key] = {"status": status, "choice": choice or {}, "comment": comment or "", "ts": time.strftime("%Y-%m-%d %H:%M:%S")}
    save_decisions(slug, d)
    # --- append to the training log
    rec = {"ts": d["items"][key]["ts"], "slug": slug, "key": key, "kind": (item or {}).get("kind"), "status": status,
           "from": (item or {}).get("current"), "to": choice or {}, "comment": comment or "", "context": (item or {}).get("context"),
           "moments": (item or {}).get("moments")}
    LEARN.mkdir(exist_ok=True)
    with open(LEARN / "feedback.jsonl", "a", encoding="utf-8") as f:
        f.write(json.dumps(rec, ensure_ascii=False) + "\n")
    # --- preference scores (undo the previous answer's effect first so re-answering does not double count)
    prefs = _prefs()
    cur_id = ((item or {}).get("current") or {}).get("asset") or ((item or {}).get("current") or {}).get("template")
    new_id = (choice or {}).get("asset") or (choice or {}).get("template")
    pk = lambda x: (f"template:{x}" if x and not str(x).startswith(("sfx", "meme", "green", "music", "image", "brand", "crodie")) and "." not in str(x) else x)  # noqa: E731
    if prev:
        p_status, p_choice = prev.get("status"), prev.get("choice") or {}
        p_new = p_choice.get("asset") or p_choice.get("template")
        if p_status == "keep":
            _bump(prefs, pk(cur_id), -0.5)
        elif p_status == "remove":
            _bump(prefs, pk(cur_id), +1.0)
        elif p_status == "change":
            _bump(prefs, pk(cur_id), +1.0)
            _bump(prefs, pk(p_new), -2.0)
    if status == "keep":
        _bump(prefs, pk(cur_id), +0.5)
    elif status == "remove":
        _bump(prefs, pk(cur_id), -1.0)
    elif status == "change":
        _bump(prefs, pk(cur_id), -1.0)
        _bump(prefs, pk(new_id), +2.0)
    _write(LEARN / "prefs.json", prefs)
    _write_notes()
    return d["items"][key]


def _write_notes() -> None:
    """learning/notes.md: the creator's comments by kind (read this at the start of every editing pass)."""
    fb = []
    try:
        for line in open(LEARN / "feedback.jsonl", encoding="utf-8"):
            try:
                fb.append(json.loads(line))
            except ValueError:
                pass
    except OSError:
        return
    latest: dict[tuple, dict] = {}
    for r in fb:                                                  # last answer per (slug,key) wins
        latest[(r["slug"], r["key"])] = r
    lines = ["# Creator feedback (auto-generated from the Review page)\n",
             "Read before editing: these are the creator's answers and comments on past edits.\n"]
    by_kind: dict[str, list] = {}
    for r in latest.values():
        by_kind.setdefault(r.get("kind") or "other", []).append(r)
    for kind, rs in sorted(by_kind.items()):
        n = len(rs)
        removed = sum(1 for r in rs if r["status"] == "remove")
        changed = sum(1 for r in rs if r["status"] == "change")
        kept = sum(1 for r in rs if r["status"] == "keep")
        lines.append(f"\n## {kind}  (kept {kept}, changed {changed}, removed {removed} of {n} reviewed)\n")
        for r in rs:
            if r.get("comment"):
                ctx = f' — he says: "{r.get("context")}"' if r.get("context") else ""
                lines.append(f"- [{r['status']}] {r['comment']}{ctx}  ({r['slug']}, {r['key'][:60]})")
    (LEARN / "notes.md").write_text("\n".join(lines) + "\n", encoding="utf-8")


def add_addition(slug: str, ad: dict) -> dict:
    d = load_decisions(slug)
    d["additions"].append(ad)
    save_decisions(slug, d)
    LEARN.mkdir(exist_ok=True)
    with open(LEARN / "feedback.jsonl", "a", encoding="utf-8") as f:
        f.write(json.dumps({"ts": time.strftime("%Y-%m-%d %H:%M:%S"), "slug": slug, "key": f"add|{len(d['additions']) - 1}",
                            "kind": "added", "status": "add", "to": ad, "comment": ad.get("comment", ""), "context": ad.get("context")},
                           ensure_ascii=False) + "\n")
    p = _prefs()
    _bump(p, ad.get("asset") or (f"template:{ad['template']}" if ad.get("template") else None), +2.0)
    _write(LEARN / "prefs.json", p)
    _write_notes()
    return d


# ------------------------------------------------------------------ apply decisions to an EDL
def apply_decisions(edl: dict, slug: str) -> dict:
    """Re-apply the creator's answers to a (re)built EDL. Items are matched by the stable keys of build_items()."""
    dec = load_decisions(slug)
    if not dec["items"] and not dec["additions"]:
        return edl
    import tempfile
    # build_items() reads edit.json from disk, so evaluate on a temp project view of this EDL
    tmp_path = PROJECTS / slug / "edit.json"
    keep_orig = tmp_path.read_text(encoding="utf-8") if tmp_path.exists() else None
    tmp_path.write_text(json.dumps(edl), encoding="utf-8")
    try:
        items = build_items(slug)["items"]
    finally:
        if keep_orig is not None:
            tmp_path.write_text(keep_orig, encoding="utf-8")
    drops = {"audio.sfx": [], "audio.music": [], "audio.bleeps": [], "overlays": [], "text": [], "segments": []}
    for it in items:
        d = dec["items"].get(it["key"])
        if not d or it["kind"] in ("scene", "added"):
            continue
        status, ch = d.get("status"), d.get("choice") or {}
        lst, idx = it["ref"]
        if status == "remove":
            drops[lst].append(idx)
        elif status == "change" and ch:
            ev = _resolve_ref(edl, lst, idx)
            if ev is None:
                continue
            if ch.get("asset"):
                ev["asset"] = ch["asset"]
                if lst == "segments":                              # meme cutaway: use the new clip's own window
                    a = _lookup(ch["asset"]) or {}
                    lo = a.get("use_in") or 0.0
                    hi = a.get("use_out") or a.get("duration_s") or lo + 2.0
                    ev["in"], ev["out"] = round(lo, 2), round(min(hi, lo + 3.0), 2)
                elif lst == "audio.sfx":
                    ev.pop("in", None)
            if ch.get("template"):
                ev["template"] = ch["template"]
            if ch.get("vars") is not None:
                ev["vars"] = ch["vars"]
            if ch.get("text") is not None and lst == "text":
                ev["text"] = ch["text"]
            if ch.get("style") and lst == "text":
                ev["style"] = ch["style"]
    for lst, idxs in drops.items():
        for idx in sorted(set(idxs), reverse=True):
            tgt = _list_ref(edl, lst)
            if tgt is not None and idx < len(tgt):
                del tgt[idx]
    # --- additions: convert output time to a segment anchor
    spans_total = 0.0
    seg_pos = []
    for s in edl["segments"]:
        d = seg_duration(s, _lookup)
        seg_pos.append((spans_total, spans_total + d, s))
        spans_total += d
    for ad in dec["additions"]:
        t = ad["out_time"]
        seg = next((s for st, en, s in seg_pos if st <= t <= en and s.get("id") and s.get("type", "source") == "source"), None)
        if not seg:
            continue
        rel = round((t - next(st for st, en, s in seg_pos if s is seg)), 3)
        anchor = {"seg": seg["id"], "rel": rel}
        k = ad.get("kind")
        if k == "sfx" and ad.get("asset"):
            edl["audio"]["sfx"].append({"asset": ad["asset"], **anchor, **({"dur": ad["dur"]} if ad.get("dur") else {})})
        elif k == "greenscreen" and ad.get("asset"):
            edl.setdefault("overlays", []).append({"type": "greenscreen", "asset": ad["asset"], **anchor, "dur": ad.get("dur", 2.5),
                                                   "x": 0.78, "y": 0.62, "scale": 0.5})
        elif k == "motion" and ad.get("template"):
            edl.setdefault("overlays", []).append({"type": "motion", "template": ad["template"], "vars": ad.get("vars") or {}, **anchor})
        elif k == "text" and ad.get("text"):
            edl.setdefault("text", []).append({"text": ad["text"], **anchor, "dur": ad.get("dur", 1.6), "style": ad.get("style", "impact"), "y": 0.3})
        elif k == "meme" and ad.get("asset"):
            a = _lookup(ad["asset"]) or {}
            lo = a.get("use_in") or 0.0
            hi = min(a.get("use_out") or a.get("duration_s") or lo + 2.0, lo + 3.0)
            i = edl["segments"].index(seg)
            edl["segments"].insert(i + 1, {"id": f"meme-add-{i}", "type": "cutaway", "asset": ad["asset"], "in": round(lo, 2), "out": round(hi, 2)})
    return edl


def _list_ref(edl: dict, lst: str):
    if lst.startswith("audio."):
        return edl.get("audio", {}).get(lst.split(".", 1)[1])
    return edl.get(lst)


def _resolve_ref(edl: dict, lst: str, idx: int):
    tgt = _list_ref(edl, lst)
    return tgt[idx] if tgt is not None and idx < len(tgt) else None


def apply_to_project(slug: str) -> dict:
    """Generic projects: edit edit.json in place (backup in history/)."""
    import shutil
    from datetime import datetime
    p = PROJECTS / slug / "edit.json"
    edl = json.loads(p.read_text(encoding="utf-8"))
    hist = PROJECTS / slug / "history"
    hist.mkdir(exist_ok=True)
    shutil.copy2(p, hist / f"edit.{datetime.now():%Y%m%d-%H%M%S}.json")
    edl = apply_decisions(edl, slug)
    validate(edl)
    p.write_text(json.dumps(edl, indent=2, ensure_ascii=False), encoding="utf-8")
    return edl


# ------------------------------------------------------------------ markdown preview
def _fmt(t: float) -> str:
    return f"{int(t // 60)}:{t % 60:04.1f}"


def to_markdown(slug: str) -> str:
    data = build_items(slug)
    dec = load_decisions(slug)
    lines = [f"# Review: {slug}", "", f"Edited length {_fmt(data['duration'])}. Open the Review page in MC Studio "
             f"(`uv run mcs ui`, then Episodes > {slug} > Review) to change anything; this file is the read-only summary.", ""]
    if dec.get("general"):
        lines += ["## Overall notes", dec["general"], ""]
    kinds = ["scene", "cinematic", "music", "meme", "greenscreen", "motion", "text", "sfx", "bleep", "image", "added"]
    for k in kinds:
        its = [i for i in data["items"] if i["kind"] == k]
        if not its:
            continue
        lines += [f"## {k} ({len(its)})", "", "| time | what | he says | answer |", "|---|---|---|---|"]
        for i in its:
            d = dec["items"].get(i["key"], {})
            ans = (d.get("status") or "").upper() + (f" — {d['comment']}" if d.get("comment") else "")
            lines.append(f"| {_fmt(i['start'])} | {i['title'][:60]} | {i['context'][:70]} | {ans} |")
        lines.append("")
    out = PROJECTS / slug / "REVIEW.md"
    out.write_text("\n".join(lines), encoding="utf-8")
    return "\n".join(lines)


def learning_summary() -> dict:
    fb = []
    try:
        for line in open(LEARN / "feedback.jsonl", encoding="utf-8"):
            try:
                fb.append(json.loads(line))
            except ValueError:
                pass
    except OSError:
        pass
    prefs = _prefs()
    top = sorted(prefs.items(), key=lambda kv: -kv[1])
    return {"answers": len(fb), "liked": [kv for kv in top if kv[1] > 0][:12], "disliked": [kv for kv in reversed(top) if kv[1] < 0][:12]}


if __name__ == "__main__":
    if len(sys.argv) >= 3 and sys.argv[1] == "md":
        to_markdown(sys.argv[2])
        print(f"wrote projects/{sys.argv[2]}/REVIEW.md")

toolu_01AJGRdvAM3vp6Nz46LXyWWM.content:
"""Review & training layer: turn an edit into a list of decisions the creator can approve / swap / remove / comment on.

    projects/<slug>/review/decisions.json   the creator's answers for THIS episode (stable keys, survive rebuilds)
    projects/<slug>/review/scenes.json      story beats written by a custom builder (optional): [{id,note,segs:[ids]}]
    studio/learning/feedback.jsonl          every decision + comment + context, appended forever (training data)
    studio/learning/prefs.json              per-asset / per-template preference score the finder uses (assets.find)
    studio/learning/notes.md                the creator's free-text comments, grouped, for the next editing pass

Used by server.py (/api/projects/<slug>/review*) and by builders (`apply_decisions(edl, slug)` re-applies the answers after
every rebuild, `removed_scenes(slug)` lists beats the creator cut).

CLI:  uv run python -m mcstudio.review md <slug>      writes projects/<slug>/REVIEW.md
"""
from __future__ import annotations

import json
import re
import sys
import time
from pathlib import Path

from . import assets as A
from .edl import EDLError, build_spans, resolve_time, seg_duration, validate
from .paths import PROJECTS, STUDIO

LEARN = STUDIO / "learning"
SFX_KINDS = ("sfx",)
ASSET_KINDS = ("sfx", "meme", "greenscreen", "image", "music")


# ------------------------------------------------------------------ small io helpers
def _read(p: Path, default=None):
    try:
        return json.loads(Path(p).read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return default


def _write(p: Path, data) -> None:
    p = Path(p)
    p.parent.mkdir(parents=True, exist_ok=True)
    tmp = p.with_name(p.name + ".tmp")
    tmp.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")
    tmp.replace(p)


def review_dir(slug: str) -> Path:
    return PROJECTS / slug / "review"


def load_decisions(slug: str) -> dict:
    d = _read(review_dir(slug) / "decisions.json", {}) or {}
    d.setdefault("items", {})
    d.setdefault("additions", [])
    d.setdefault("general", "")
    return d


def save_decisions(slug: str, d: dict) -> None:
    d["updated"] = time.strftime("%Y-%m-%d %H:%M:%S")
    _write(review_dir(slug) / "decisions.json", d)


def removed_scenes(slug: str) -> set[str]:
    """Story beats (by note) the creator cut; custom builders skip them on the next rebuild."""
    return {k.split("|", 1)[1] for k, v in load_decisions(slug)["items"].items()
            if k.startswith("scene|") and v.get("status") == "remove"}


# ------------------------------------------------------------------ context helpers
def _words(slug: str) -> list[dict]:
    tr = _read(PROJECTS / slug / "work" / "transcript.json", {"segments": []}) or {"segments": []}
    return [w for s in tr.get("segments", []) for w in s.get("words", [])]


def _context(words: list[dict], src: float | None, before=2.5, after=3.5, cap=16) -> str:
    if src is None or not words:
        return ""
    ws = [w["word"].strip() for w in words if src - before <= w["start"] <= src + after]
    return " ".join(ws[:cap])


def _moments_from_text(text: str) -> list[str]:
    try:
        from .autoplan import LEXICON
    except Exception:  # noqa: BLE001
        return []
    t = re.sub(r"[^\w' ?!]", "", text.lower())
    out: list[str] = []
    for rx, moment, _score, _tmpl in LEXICON:
        if re.search(rx, t) and moment not in out:
            out.append(moment)
    return out[:3]


def _lookup(i):
    try:
        return A.get(i)
    except KeyError:
        return None


def _asset_brief(a: dict | None) -> dict | None:
    if not a:
        return None
    return {k: a.get(k) for k in ("id", "title", "category", "kind", "duration_s", "thumb", "root", "path", "moments",
                                  "roles", "description", "peak_s", "content_rating", "key_mode", "favorite",
                                  "copyright_risk", "notes")}


# ------------------------------------------------------------------ build the review items from edit.json
def build_items(slug: str) -> dict:
    p = PROJECTS / slug
    edl = _read(p / "edit.json")
    if not edl:
        return {"items": [], "duration": 0, "warnings": ["no edit.json yet"]}
    warnings: list[str] = []
    try:
        validate(edl)
        spans = build_spans(edl, _lookup)
    except (EDLError, KeyError, TypeError) as e:
        return {"items": [], "duration": 0, "warnings": [f"EDL error: {e}"]}
    words = _words(slug)
    segs = edl["segments"]
    seg_t: dict[str, tuple[float, float, dict]] = {}
    t = 0.0
    for i, s in enumerate(segs):
        d = seg_duration(s, _lookup)
        seg_t[s.get("id") or f"seg{i}"] = (t, t + d, s)
        t += d
    total = t

    def src_at_out(ot: float) -> float | None:
        for st, en, s in seg_t.values():
            if s.get("type", "source") == "source" and st - 1e-6 <= ot <= en + 1e-6:
                return s["in"] + (ot - st) * s.get("speed", 1.0)
        return None

    def src_of(ev: dict, at: float) -> float | None:
        if "src_at" in ev:
            return ev["src_at"]
        if ev.get("seg") in seg_t and "rel" in ev:
            s = seg_t[ev["seg"]][2]
            return s.get("in", 0) + ev["rel"] * s.get("speed", 1.0) if s.get("type", "source") == "source" else None
        return src_at_out(at)

    items: list[dict] = []
    seen: dict[str, int] = {}

    def add(kind, ev_ref, start, end, key_core, title, current, src, asset_id=None):
        n = seen.get(key_core, 0)
        seen[key_core] = n + 1
        key = key_core if n == 0 else f"{key_core}#{n}"
        ctx = _context(words, src)
        items.append({"key": key, "kind": kind, "ref": ev_ref, "start": round(start, 2), "end": round(max(end, start + 0.4), 2),
                      "title": title, "current": current, "src": None if src is None else round(src, 2), "context": ctx,
                      "moments": _moments_from_text(ctx), "asset": asset_id})

    def anchor(ev, at, src):
        return f"{round(src, 1)}" if src is not None else f"o{round(at, 1)}"

    # --- audio: sfx
    for k, ev in enumerate(edl.get("audio", {}).get("sfx", [])):
        if not ev.get("asset"):
            continue                                                  # pre-mixed montage hit tracks etc.
        at = resolve_time(ev, spans, warnings, f"sfx[{k}]") if ("at" in ev or "src_at" in ev or "seg" in ev) else None
        if at is None:
            continue
        a = _lookup(ev["asset"])
        dur = ev.get("dur") or (a or {}).get("tail_s") or (a or {}).get("duration_s") or 1.0
        src = src_of(ev, at)
        add("sfx", ["audio.sfx", k], at, at + dur, f"sfx|{ev['asset']}|{anchor(ev, at, src)}", (a or {}).get("title") or ev["asset"],
            {"asset": ev["asset"]}, src, ev["asset"])
    # --- overlays
    for k, ev in enumerate(edl.get("overlays", [])):
        at = resolve_time(ev, spans, warnings, f"overlay[{k}]") if ("at" in ev or "src_at" in ev or "seg" in ev) else None
        if at is None:
            continue
        src = src_of(ev, at)
        dur = ev.get("dur") or 2.0
        typ = ev.get("type")
        if ev.get("cinematic"):
            add("cinematic", ["overlays", k], at, at + dur, f"cin|{ev.get('cinematic')}", f"Flashback shot: {ev.get('cinematic')}",
                {"file": ev.get("file")}, src)
        elif typ == "greenscreen":
            a = _lookup(ev.get("asset", ""))
            add("greenscreen", ["overlays", k], at, at + dur, f"gs|{ev.get('asset')}|{anchor(ev, at, src)}", (a or {}).get("title") or ev.get("asset"),
                {"asset": ev.get("asset")}, src, ev.get("asset"))
        elif typ == "motion":
            tpl = ev.get("template") or ev.get("file")
            add("motion", ["overlays", k], at, at + dur, f"mo|{tpl}|{anchor(ev, at, src)}", f"Graphic: {tpl}",
                {"template": ev.get("template"), "vars": ev.get("vars") or {}}, src)
        elif typ in ("image", "video"):
            a = _lookup(ev.get("asset", "")) if ev.get("asset") else None
            add("image", ["overlays", k], at, at + dur, f"img|{ev.get('asset') or ev.get('file')}|{anchor(ev, at, src)}",
                (a or {}).get("title") or ev.get("file") or ev.get("asset"), {"asset": ev.get("asset")}, src, ev.get("asset"))
    # --- text pops
    for k, ev in enumerate(edl.get("text", [])):
        at = resolve_time(ev, spans, warnings, f"text[{k}]") if ("at" in ev or "src_at" in ev or "seg" in ev) else None
        if at is None:
            continue
        src = src_of(ev, at)
        add("text", ["text", k], at, at + (ev.get("dur") or 1.2), f"tx|{ev.get('text', '')[:24]}|{anchor(ev, at, src)}",
            f"Text: {ev.get('text', '')}", {"text": ev.get("text"), "style": ev.get("style", "impact")}, src)
    # --- meme cutaways (segments of type cutaway)
    for i, s in enumerate(segs):
        if s.get("type") != "cutaway":
            continue
        st, en, _ = seg_t[s.get("id") or f"seg{i}"]
        prev = next((x for x in reversed(segs[:i]) if x.get("type", "source") == "source"), None)
        src = prev["out"] if prev else None
        a = _lookup(s.get("asset", ""))
        add("meme", ["segments", i], st, en, f"meme|{s.get('asset')}|{anchor(s, st, src)}", (a or {}).get("title") or s.get("asset"),
            {"asset": s.get("asset")}, src, s.get("asset"))
    # --- music beds
    for k, ev in enumerate(edl.get("audio", {}).get("music", [])):
        at = ev.get("at", 0.0)
        a = _lookup(ev.get("asset", ""))
        add("music", ["audio.music", k], at, ev.get("until", total), f"music|{ev.get('asset')}|{int(at // 15)}",
            f"Music: {(a or {}).get('title') or ev.get('asset')}", {"asset": ev.get("asset")}, src_at_out(at + 3), ev.get("asset"))
    # --- bleeps
    for k, ev in enumerate(edl.get("audio", {}).get("bleeps", [])):
        at = resolve_time(ev, spans, warnings, f"bleep[{k}]") if ("at" in ev or "src_at" in ev) else None
        if at is None:
            continue
        add("bleep", ["audio.bleeps", k], at, at + (ev.get("dur") or 0.4), f"bleep|{round(ev.get('src_at', at), 1)}", "Bleep (swear covered)",
            {}, ev.get("src_at"))
    # --- story beats written by a custom builder
    scenes = _read(review_dir(slug) / "scenes.json", []) or []
    for sc in scenes:
        ids = [i for i in sc.get("segs", []) if i in seg_t]
        if not ids:
            continue
        st = min(seg_t[i][0] for i in ids)
        en = max(seg_t[i][1] for i in ids)
        add("scene", ["scene", sc["note"]], st, en, f"scene|{sc['note']}", f"Scene: {sc['note']}",
            {"note": sc["note"], "act": sc.get("act")}, src_at_out(st + 1), None)
    # --- additions the creator made in the review page
    dec = load_decisions(slug)
    for n, ad in enumerate(dec["additions"]):
        add("added", ["addition", n], ad["out_time"], ad["out_time"] + 2.0, f"add|{n}", f"Added {ad['kind']}: {ad.get('label') or ''}",
            {k: v for k, v in ad.items() if k not in ("comment",)}, src_at_out(ad["out_time"]), ad.get("asset"))
    items.sort(key=lambda x: (x["start"], x["kind"]))
    return {"items": items, "duration": round(total, 2), "warnings": warnings[:20]}


# ------------------------------------------------------------------ recommendations
def options(slug: str, key: str, q: str = "", limit: int = 8) -> list[dict]:
    """Recommended alternatives for one review item (the same finder/scorer the planner uses)."""
    items = {i["key"]: i for i in build_items(slug)["items"]}
    it = items.get(key)
    if not it:
        return []
    kind = it["kind"]
    cats = {"sfx": ["sfx_meme", "sfx_ui", "sfx_minecraft", "sfx_mlg", "sfx_laugh"], "meme": ["meme_video"],
            "greenscreen": ["green_screen"], "image": ["image", "brand_sticker"], "music": ["music", "sfx_meme"],
            "added": []}.get(kind, [])
    cur = _lookup(it.get("asset") or "") if it.get("asset") else None
    if kind == "added":
        k2 = (it["current"] or {}).get("kind")
        cats = {"sfx": ["sfx_meme", "sfx_ui", "sfx_minecraft", "sfx_mlg"], "meme": ["meme_video"], "greenscreen": ["green_screen"]}.get(k2, [])
    if not cats:
        return []
    moments = list(dict.fromkeys(it.get("moments", []) + ((cur or {}).get("moments") or [])[:2]))[:4] or ["emphasis"]
    roles = ((cur or {}).get("roles") or [])[:1] if kind == "sfx" else []
    res = A.find(A.Query(moments=moments, roles=roles, categories=cats, text=q or None, project=slug, limit=limit + 4,
                         max_rating="mild", max_duration=(12 if kind != "music" else None),
                         min_duration=(60 if kind == "music" else None)))
    out = []
    for r in res:
        if r["id"] == it.get("asset"):
            continue
        out.append(_asset_brief(r))
        if len(out) >= limit:
            break
    return out


# ------------------------------------------------------------------ learning log + preferences
def _prefs() -> dict:
    return _read(LEARN / "prefs.json", {}) or {}


def asset_pref(asset_id: str) -> float:
    """Preference score for the finder (assets.find adds 0.35 * this, clamped)."""
    return float(_prefs().get(asset_id, 0.0))


def _bump(prefs: dict, key: str | None, delta: float) -> None:
    if key:
        prefs[key] = round(max(-4.0, min(4.0, prefs.get(key, 0.0) + delta)), 2)


def record_decision(slug: str, key: str, status: str, choice: dict | None, comment: str, item: dict | None) -> dict:
    d = load_decisions(slug)
    prev = d["items"].get(key, {})
    d["items"][key] = {"status": status, "choice": choice or {}, "comment": comment or "", "ts": time.strftime("%Y-%m-%d %H:%M:%S")}
    save_decisions(slug, d)
    # --- append to the training log
    rec = {"ts": d["items"][key]["ts"], "slug": slug, "key": key, "kind": (item or {}).get("kind"), "status": status,
           "from": (item or {}).get("current"), "to": choice or {}, "comment": comment or "", "context": (item or {}).get("context"),
           "moments": (item or {}).get("moments")}
    LEARN.mkdir(exist_ok=True)
    with open(LEARN / "feedback.jsonl", "a", encoding="utf-8") as f:
        f.write(json.dumps(rec, ensure_ascii=False) + "\n")
    # --- preference scores (undo the previous answer's effect first so re-answering does not double count)
    prefs = _prefs()
    cur_id = ((item or {}).get("current") or {}).get("asset") or ((item or {}).get("current") or {}).get("template")
    new_id = (choice or {}).get("asset") or (choice or {}).get("template")
    pk = lambda x: (f"template:{x}" if x and not str(x).startswith(("sfx", "meme", "green", "music", "image", "brand", "crodie")) and "." not in str(x) else x)  # noqa: E731
    if prev:
        p_status, p_choice = prev.get("status"), prev.get("choice") or {}
        p_new = p_choice.get("asset") or p_choice.get("template")
        if p_status == "keep":
            _bump(prefs, pk(cur_id), -0.5)
        elif p_status == "remove":
            _bump(prefs, pk(cur_id), +1.0)
        elif p_status == "change":
            _bump(prefs, pk(cur_id), +1.0)
            _bump(prefs, pk(p_new), -2.0)
    if status == "keep":
        _bump(prefs, pk(cur_id), +0.5)
    elif status == "remove":
        _bump(prefs, pk(cur_id), -1.0)
    elif status == "change":
        _bump(prefs, pk(cur_id), -1.0)
        _bump(prefs, pk(new_id), +2.0)
    _write(LEARN / "prefs.json", prefs)
    _write_notes()
    return d["items"][key]


def _write_notes() -> None:
    """learning/notes.md: the creator's comments by kind (read this at the start of every editing pass)."""
    fb = []
    try:
        for line in open(LEARN / "feedback.jsonl", encoding="utf-8"):
            try:
                fb.append(json.loads(line))
            except ValueError:
                pass
    except OSError:
        return
    latest: dict[tuple, dict] = {}
    for r in fb:                                                  # last answer per (slug,key) wins
        latest[(r["slug"], r["key"])] = r
    lines = ["# Creator feedback (auto-generated from the Review page)\n",
             "Read before editing: these are the creator's answers and comments on past edits.\n"]
    by_kind: dict[str, list] = {}
    for r in latest.values():
        by_kind.setdefault(r.get("kind") or "other", []).append(r)
    for kind, rs in sorted(by_kind.items()):
        n = len(rs)
        removed = sum(1 for r in rs if r["status"] == "remove")
        changed = sum(1 for r in rs if r["status"] == "change")
        kept = sum(1 for r in rs if r["status"] == "keep")
        lines.append(f"\n## {kind}  (kept {kept}, changed {changed}, removed {removed} of {n} reviewed)\n")
        for r in rs:
            if r.get("comment"):
                ctx = f' — he says: "{r.get("context")}"' if r.get("context") else ""
                lines.append(f"- [{r['status']}] {r['comment']}{ctx}  ({r['slug']}, {r['key'][:60]})")
    (LEARN / "notes.md").write_text("\n".join(lines) + "\n", encoding="utf-8")


def add_addition(slug: str, ad: dict) -> dict:
    d = load_decisions(slug)
    d["additions"].append(ad)
    save_decisions(slug, d)
    LEARN.mkdir(exist_ok=True)
    with open(LEARN / "feedback.jsonl", "a", encoding="utf-8") as f:
        f.write(json.dumps({"ts": time.strftime("%Y-%m-%d %H:%M:%S"), "slug": slug, "key": f"add|{len(d['additions']) - 1}",
                            "kind": "added", "status": "add", "to": ad, "comment": ad.get("comment", ""), "context": ad.get("context")},
                           ensure_ascii=False) + "\n")
    p = _prefs()
    _bump(p, ad.get("asset") or (f"template:{ad['template']}" if ad.get("template") else None), +2.0)
    _write(LEARN / "prefs.json", p)
    _write_notes()
    return d


# ------------------------------------------------------------------ apply decisions to an EDL
def apply_decisions(edl: dict, slug: str) -> dict:
    """Re-apply the creator's answers to a (re)built EDL. Items are matched by the stable keys of build_items()."""
    dec = load_decisions(slug)
    if not dec["items"] and not dec["additions"]:
        return edl
    import tempfile
    # build_items() reads edit.json from disk, so evaluate on a temp project view of this EDL
    tmp_path = PROJECTS / slug / "edit.json"
    keep_orig = tmp_path.read_text(encoding="utf-8") if tmp_path.exists() else None
    tmp_path.write_text(json.dumps(edl), encoding="utf-8")
    try:
        items = build_items(slug)["items"]
    finally:
        if keep_orig is not None:
            tmp_path.write_text(keep_orig, encoding="utf-8")
    drops = {"audio.sfx": [], "audio.music": [], "audio.bleeps": [], "overlays": [], "text": [], "segments": []}
    for it in items:
        d = dec["items"].get(it["key"])
        if not d or it["kind"] in ("scene", "added"):
            continue
        status, ch = d.get("status"), d.get("choice") or {}
        lst, idx = it["ref"]
        if status == "remove":
            drops[lst].append(idx)
        elif status == "change" and ch:
            ev = _resolve_ref(edl, lst, idx)
            if ev is None:
                continue
            if ch.get("asset"):
                ev["asset"] = ch["asset"]
                if lst == "segments":                              # meme cutaway: use the new clip's own window
                    a = _lookup(ch["asset"]) or {}
                    lo = a.get("use_in") or 0.0
                    hi = a.get("use_out") or a.get("duration_s") or lo + 2.0
                    ev["in"], ev["out"] = round(lo, 2), round(min(hi, lo + 3.0), 2)
                elif lst == "audio.sfx":
                    ev.pop("in", None)
            if ch.get("template"):
                ev["template"] = ch["template"]
            if ch.get("vars") is not None:
                ev["vars"] = ch["vars"]
            if ch.get("text") is not None and lst == "text":
                ev["text"] = ch["text"]
            if ch.get("style") and lst == "text":
                ev["style"] = ch["style"]
    for lst, idxs in drops.items():
        for idx in sorted(set(idxs), reverse=True):
            tgt = _list_ref(edl, lst)
            if tgt is not None and idx < len(tgt):
                del tgt[idx]
    # --- additions: convert output time to a segment anchor
    spans_total = 0.0
    seg_pos = []
    for s in edl["segments"]:
        d = seg_duration(s, _lookup)
        seg_pos.append((spans_total, spans_total + d, s))
        spans_total += d
    for ad in dec["additions"]:
        t = ad["out_time"]
        seg = next((s for st, en, s in seg_pos if st <= t <= en and s.get("id") and s.get("type", "source") == "source"), None)
        if not seg:
            continue
        rel = round((t - next(st for st, en, s in seg_pos if s is seg)), 3)
        anchor = {"seg": seg["id"], "rel": rel}
        k = ad.get("kind")
        if k == "sfx" and ad.get("asset"):
            edl["audio"]["sfx"].append({"asset": ad["asset"], **anchor, **({"dur": ad["dur"]} if ad.get("dur") else {})})
        elif k == "greenscreen" and ad.get("asset"):
            edl.setdefault("overlays", []).append({"type": "greenscreen", "asset": ad["asset"], **anchor, "dur": ad.get("dur", 2.5),
                                                   "x": 0.78, "y": 0.62, "scale": 0.5})
        elif k == "motion" and ad.get("template"):
            edl.setdefault("overlays", []).append({"type": "motion", "template": ad["template"], "vars": ad.get("vars") or {}, **anchor})
        elif k == "text" and ad.get("text"):
            edl.setdefault("text", []).append({"text": ad["text"], **anchor, "dur": ad.get("dur", 1.6), "style": ad.get("style", "impact"), "y": 0.3})
        elif k == "meme" and ad.get("asset"):
            a = _lookup(ad["asset"]) or {}
            lo = a.get("use_in") or 0.0
            hi = min(a.get("use_out") or a.get("duration_s") or lo + 2.0, lo + 3.0)
            i = edl["segments"].index(seg)
            edl["segments"].insert(i + 1, {"id": f"meme-add-{i}", "type": "cutaway", "asset": ad["asset"], "in": round(lo, 2), "out": round(hi, 2)})
    return edl


def _list_ref(edl: dict, lst: str):
    if lst.startswith("audio."):
        return edl.get("audio", {}).get(lst.split(".", 1)[1])
    return edl.get(lst)


def _resolve_ref(edl: dict, lst: str, idx: int):
    tgt = _list_ref(edl, lst)
    return tgt[idx] if tgt is not None and idx < len(tgt) else None


def apply_to_project(slug: str) -> dict:
    """Generic projects: edit edit.json in place (backup in history/)."""
    import shutil
    from datetime import datetime
    p = PROJECTS / slug / "edit.json"
    edl = json.loads(p.read_text(encoding="utf-8"))
    hist = PROJECTS / slug / "history"
    hist.mkdir(exist_ok=True)
    shutil.copy2(p, hist / f"edit.{datetime.now():%Y%m%d-%H%M%S}.json")
    edl = apply_decisions(edl, slug)
    validate(edl)
    p.write_text(json.dumps(edl, indent=2, ensure_ascii=False), encoding="utf-8")
    return edl


# ------------------------------------------------------------------ markdown preview
def _fmt(t: float) -> str:
    return f"{int(t // 60)}:{t % 60:04.1f}"


def to_markdown(slug: str) -> str:
    data = build_items(slug)
    dec = load_decisions(slug)
    lines = [f"# Review: {slug}", "", f"Edited length {_fmt(data['duration'])}. Open the Review page in MC Studio "
             f"(`uv run mcs ui`, then Episodes > {slug} > Review) to change anything; this file is the read-only summary.", ""]
    if dec.get("general"):
        lines += ["## Overall notes", dec["general"], ""]
    kinds = ["scene", "cinematic", "music", "meme", "greenscreen", "motion", "text", "sfx", "bleep", "image", "added"]
    for k in kinds:
        its = [i for i in data["items"] if i["kind"] == k]
        if not its:
            continue
        lines += [f"## {k} ({len(its)})", "", "| time | what | he says | answer |", "|---|---|---|---|"]
        for i in its:
            d = dec["items"].get(i["key"], {})
            ans = (d.get("status") or "").upper() + (f" — {d['comment']}" if d.get("comment") else "")
            lines.append(f"| {_fmt(i['start'])} | {i['title'][:60]} | {i['context'][:70]} | {ans} |")
        lines.append("")
    out = PROJECTS / slug / "REVIEW.md"
    out.write_text("\n".join(lines), encoding="utf-8")
    return "\n".join(lines)


def learning_summary() -> dict:
    fb = []
    try:
        for line in open(LEARN / "feedback.jsonl", encoding="utf-8"):
            try:
                fb.append(json.loads(line))
            except ValueError:
                pass
    except OSError:
        pass
    prefs = _prefs()
    top = sorted(prefs.items(), key=lambda kv: -kv[1])
    return {"answers": len(fb), "liked": [kv for kv in top if kv[1] > 0][:12], "disliked": [kv for kv in reversed(top) if kv[1] < 0][:12]}


if __name__ == "__main__":
    if len(sys.argv) >= 3 and sys.argv[1] == "md":
        to_markdown(sys.argv[2])
        print(f"wrote projects/{sys.argv[2]}/REVIEW.md")

