// Review & training page: full editor timeline + every edit decision (approve / swap / remove / comment) with a live preview.
// Answers are saved per episode and logged to studio/learning (the finder learns from them). "Apply" rebuilds the edit and
// re-renders the preview. Helpers come from app.js through `H`.
export async function ReviewPage(H, slug) {
  const { $, $$, api, toast, esc, fmt, view, packUrl, thumbUrl, pollers, store } = H;
  const S = encodeURIComponent(slug);
  let data;
  try { data = await api(`/api/projects/${S}/review`); } catch (e) { view.innerHTML = `<div class="empty">${esc(e.message)}</div>`; return; }
  let tl = { duration: 0, tracks: {}, warnings: [] };
  try { tl = await api(`/api/projects/${S}/timeline`); } catch {}
  const KINDS = [["scene", "Scenes"], ["cinematic", "Drone / replay shots"], ["music", "Music"], ["meme", "Memes"], ["greenscreen", "Green screens"],
    ["motion", "Motion graphics"], ["text", "Text"], ["sfx", "Sound effects"], ["bleep", "Bleeps"], ["image", "Images"], ["added", "Added by you"]];
  const KCOLOR = { scene: "#6fbf4f", cinematic: "#4fb3ab", music: "#6f86d8", meme: "#b07fd8", greenscreen: "#d48a3a", motion: "#4fb3ab", text: "#d4b040", sfx: "#d46060", bleep: "#999", image: "#4fb3ab", added: "#ffcc33" };
  const dec = data.decisions;
  const F = store.get("rvfilter:" + slug, { kinds: ["scene", "cinematic", "music", "meme", "greenscreen", "motion", "text"], undecided: false });
  const items = data.items;
  const byRef = {};
  items.forEach((it) => { if (it.ref) byRef[it.ref.join(":")] = it; });
  const statusOf = (it) => (dec.items[it.key] || {}).status || "";
  const prev = data.preview;
  const vurl = prev ? `/media/project/${S}/out/${encodeURIComponent(prev.name)}?v=${Math.round(prev.mtime)}` : "";

  view.innerHTML = `
    <div class="row"><div><h1>Review &amp; train: ${esc(slug)}</h1>
      <p class="sub">Every choice in this edit. Keep it, swap it for a recommendation (or search anything), remove it, or just leave a comment. Your answers rebuild this video and teach the auto-editor for the next one.</p></div></div>
    ${prev && prev.stale ? `<div class="card warn" style="margin-bottom:10px">The preview video is older than the current edit. Press <b>Apply &amp; re-render preview</b> to refresh it.</div>` : ""}
    <div class="rv-top">
      <div class="rv-player">${prev ? `<video id="rvVid" controls src="${vurl}"></video>` : `<div class="empty">No preview render yet. Press Apply &amp; re-render.</div>`}
        <div class="faint" id="rvNow" style="font-size:12px;margin-top:4px">${prev ? esc(prev.name) : ""}</div></div>
      <div class="rv-side card">
        <div class="row"><b>${items.length}</b> decisions · <b id="rvDone">0</b> answered <span class="spacer"></span>
          <button class="btn gold" id="rvApply">Apply &amp; re-render preview</button></div>
        <div class="rv-prog"><div id="rvBar"></div></div>
        <div id="rvJob" class="muted mono" style="font-size:11px;white-space:pre-wrap"></div>
        <div class="rv-chips" id="rvKinds">${KINDS.map(([k, l]) => `<span class="rchip ${F.kinds.includes(k) ? "on" : ""}" data-k="${k}">${l} <i>${items.filter((i) => i.kind === k).length}</i></span>`).join("")}</div>
        <label class="rchip ${F.undecided ? "on" : ""}" id="rvUnd">only show unanswered</label>
        <textarea id="rvGeneral" rows="3" placeholder="Overall comments for this video (pacing, what felt random, what you loved)…">${esc(dec.general || "")}</textarea>
        <div class="row"><button class="btn small" id="rvMd">Open REVIEW.md</button>
          <button class="btn small" id="rvAddOpen">＋ Add something at the current time</button></div>
        <div class="faint" style="font-size:11px">Learned so far: ${data.summary.answers} answers${data.summary.liked.length ? ` · likes ${data.summary.liked.slice(0, 3).map((x) => esc(x[0].replace(/^.*\./, ""))).join(", ")}` : ""}</div>
      </div>
    </div>
    <h2 style="margin:16px 0 6px">Timeline <span class="muted" style="font-size:12px;font-weight:400">every split clip and edit · click a block to jump there and open its card · ${fmt(tl.duration)} total</span></h2>
    <div class="row" style="margin-bottom:4px"><span class="muted" style="font-size:12px">zoom</span><input type="range" id="rvZoom" min="3" max="120" value="${store.get("rvzoom", 14)}"><span class="spacer"></span>
      <span class="muted" id="rvClip" style="font-size:12px"></span></div>
    <div class="tl" id="rvTl"></div>
    <div id="rvList" style="margin-top:14px"></div>
    <div id="rvModal"></div>`;

  const vid = $("#rvVid");
  const refresh = () => {
    const n = items.filter((i) => statusOf(i)).length;
    $("#rvDone").textContent = n;
    $("#rvBar").style.width = Math.round((100 * n) / Math.max(1, items.length)) + "%";
  };
  const seek = (t, play = true, until = null) => {
    if (!vid) return;
    vid.currentTime = Math.max(0, t);
    if (play) vid.play().catch(() => {});
    clearTimeout(seek._t);
    if (until) seek._t = setTimeout(() => vid.pause(), Math.max(500, (until - t) * 1000));
  };

  // ------------------------------------------------------------- timeline
  const TRACKS = [["scenes", "Scenes"], ["segments", "Video clips"], ["zooms", "Zoom/shake"], ["overlays", "Overlays"], ["text", "Text"], ["sfx", "SFX"], ["music", "Music"], ["bleeps", "Bleeps"]];
  tl.tracks.scenes = items.filter((i) => i.kind === "scene").map((i) => ({ ...i, label: i.title.replace("Scene: ", ""), _item: i }));
  const drawTl = (pps) => {
    const W = Math.max(tl.duration * pps, 300);
    const step = pps > 40 ? 5 : pps > 14 ? 15 : pps > 6 ? 30 : 60;
    let ruler = "";
    for (let t = 0; t <= tl.duration; t += step) ruler += `<span style="left:${t * pps}px">${fmt(t).replace(/\.\d$/, "")}</span>`;
    const refKey = { sfx: "audio.sfx", overlays: "overlays", text: "text", music: "audio.music", bleeps: "audio.bleeps" };
    $("#rvTl").innerHTML = `<div class="tl-inner" style="width:${W + 84}px"><div class="tl-ruler" style="width:${W}px">${ruler}</div>
      ${TRACKS.filter(([k]) => (tl.tracks[k] || []).length).map(([k, name]) => `<div class="tl-track"><div class="tl-name">${name}</div><div class="tl-lane">
        ${tl.tracks[k].map((it, i) => {
          let item = it._item, cls = "ti-" + k;
          if (k === "segments") cls = "ti-" + it.type;
          if (!item && refKey[k]) item = byRef[refKey[k] + ":" + it.k];
          if (k === "segments" && it.type === "cutaway") item = byRef["segments:" + it.i];
          const st = item ? statusOf(item) : "";
          return `<div class="tl-item ${cls} ${st ? "st-" + st : ""}" data-k="${k}" data-i="${i}" style="left:${it.start * pps}px;width:${Math.max(3, (it.end - it.start) * pps - 1)}px" title="${esc(it.label)}  ${fmt(it.start)}–${fmt(it.end)}">${esc(it.label)}</div>`;
        }).join("")}</div></div>`).join("")}<div class="tl-head" id="rvHead" style="left:84px"></div></div>`;
    $$("#rvTl .tl-item").forEach((b) => (b.onclick = (e) => {
      e.stopPropagation();
      const k = b.dataset.k, it = tl.tracks[k][b.dataset.i];
      seek(it.start - 1.2, true, it.end + 1.0);
      $("#rvClip").textContent = `${k}: ${it.label} · ${fmt(it.start)}–${fmt(it.end)}` +
        (it.src_in != null ? ` · source ${fmt(it.src_in)}→${fmt(it.src_out)}${it.speed !== 1 ? ` @${it.speed}×` : ""}` : "");
      let item = it._item;
      const rk = { sfx: "audio.sfx", overlays: "overlays", text: "text", music: "audio.music", bleeps: "audio.bleeps" }[k];
      if (!item && rk) item = byRef[rk + ":" + it.k];
      if (k === "segments" && it.type === "cutaway") item = byRef["segments:" + it.i];
      if (item) openCard(item.key);
    }));
    $("#rvTl .tl-inner").onclick = (e) => { const r = $("#rvTl .tl-inner").getBoundingClientRect(); seek(Math.max(0, (e.clientX - r.left - 84) / pps), false); };
    drawTl._pps = pps;
  };
  drawTl(store.get("rvzoom", 14));
  $("#rvZoom").oninput = (e) => { store.set("rvzoom", +e.target.value); drawTl(+e.target.value); };
  vid?.addEventListener("timeupdate", () => { const h = $("#rvHead"); if (h) h.style.left = 84 + vid.currentTime * drawTl._pps + "px"; });

  // ------------------------------------------------------------- cards
  function cardHtml(it) {
    const d = dec.items[it.key] || {};
    const c = it.current || {};
    const st = d.status || "";
    const cur = c.asset ? `<span class="mono">${esc(c.asset)}</span>` : c.template ? `<span class="mono">${esc(c.template)}</span>` : c.text != null ? `“${esc(c.text)}”` : "";
    const chosen = d.status === "change" && d.choice ? `<div class="rv-chosen">→ you chose: <b>${esc(d.choice.asset || d.choice.template || d.choice.text || "")}</b></div>` : "";
    return `<div class="rv-card ${st ? "st-" + st : ""}" id="c-${cssId(it.key)}" data-key="${esc(it.key)}">
      <div class="rv-head"><span class="rv-time" data-t="${it.start}" data-e="${it.end}">▶ ${fmt(it.start)}</span>
        <span class="rv-kind" style="background:${KCOLOR[it.kind] || "#666"}33;border-color:${KCOLOR[it.kind] || "#666"}">${it.kind}</span>
        <b class="rv-title">${esc(it.title)}</b><span class="spacer"></span><span class="rv-st">${st ? { keep: "✓ kept", change: "✎ changed", remove: "✕ removed", comment: "💬" }[st] || st : ""}</span></div>
      ${it.context ? `<div class="rv-ctx">he says: “${esc(it.context)}”</div>` : ""}
      <div class="rv-cur">now: ${cur} ${c.asset && ["sfx", "meme", "greenscreen", "music", "image"].includes(it.kind) ? `<button class="btn small rv-listen">▶ preview asset</button>` : ""}</div>
      ${chosen}
      <div class="rv-actions">
        ${it.kind === "added" ? "" : `<button class="btn small rv-keep ${st === "keep" ? "on" : ""}">✓ Keep</button>`}
        ${["sfx", "meme", "greenscreen", "music", "image", "added"].includes(it.kind) ? `<button class="btn small rv-change">✎ Swap…</button>` : ""}
        ${it.kind === "motion" || it.kind === "text" ? `<button class="btn small rv-edit">✎ Edit…</button>` : ""}
        <button class="btn small danger rv-remove ${st === "remove" ? "on" : ""}">✕ ${it.kind === "scene" ? "Cut this scene" : "Remove"}</button>
        <input class="rv-comment" placeholder="Comment (why / what you'd rather see)…" value="${esc(d.comment || "")}"></div>
      <div class="rv-opts" hidden></div></div>`;
  }
  const cssId = (k) => k.replace(/[^a-zA-Z0-9]/g, "_");
  function renderList() {
    const vis = items.filter((i) => F.kinds.includes(i.kind) && (!F.undecided || !statusOf(i)));
    $("#rvList").innerHTML = vis.length ? vis.map(cardHtml).join("") : `<div class="empty">Nothing to show with these filters.</div>`;
    $$("#rvList .rv-card").forEach(wireCard);
    refresh();
  }
  const itemOf = (key) => items.find((i) => i.key === key);
  async function save(key, status, choice, comment) {
    const d = await api(`/api/projects/${S}/review/decision`, { method: "POST", body: { key, status, choice: choice || null, comment: comment ?? "" } });
    dec.items[key] = d;
    const it = itemOf(key), el = $("#c-" + cssId(key));
    if (el) { el.outerHTML = cardHtml(it); wireCard($("#c-" + cssId(key))); }
    drawTl(drawTl._pps);
    refresh();
  }
  function wireCard(el) {
    const key = el.dataset.key, it = itemOf(key);
    const comment = () => $(".rv-comment", el).value;
    $(".rv-time", el).onclick = () => seek(it.start - 1.5, true, it.end + 1.0);
    $(".rv-keep", el)?.addEventListener("click", () => save(key, "keep", null, comment()));
    $(".rv-remove", el).addEventListener("click", () => save(key, "remove", null, comment()));
    $(".rv-comment", el).addEventListener("change", () => save(key, statusOf(it) || "comment", (dec.items[key] || {}).choice, comment()));
    $(".rv-listen", el)?.addEventListener("click", async (e) => {
      const a = await api("/api/assets/" + encodeURIComponent(it.current.asset)).catch(() => null);
      if (a) playAssetBtn(a, e.target);
    });
    $(".rv-change", el)?.addEventListener("click", () => openOptions(el, it));
    $(".rv-edit", el)?.addEventListener("click", () => openEdit(el, it));
  }
  function openCard(key) {
    const it = itemOf(key);
    if (!it) return;
    if (!F.kinds.includes(it.kind)) { F.kinds.push(it.kind); store.set("rvfilter:" + slug, F); $$("#rvKinds .rchip").forEach((c) => c.classList.toggle("on", F.kinds.includes(c.dataset.k))); renderList(); }
    const el = $("#c-" + cssId(key));
    if (el) { el.scrollIntoView({ behavior: "smooth", block: "center" }); el.classList.add("flash"); setTimeout(() => el.classList.remove("flash"), 1600); }
  }
  function playAssetBtn(a, btn) {
    const p = $("#player");
    if (!p.paused && p.dataset.id === a.id) { p.pause(); btn.textContent = "▶ preview asset"; return; }
    p.src = packUrl(a.path, a.root); p.dataset.id = a.id; p.currentTime = 0;
    p.play().then(() => (btn.textContent = "❚❚ stop")).catch(() => toast("Can't play this in the browser", true));
    p.onended = () => (btn.textContent = "▶ preview asset");
  }
  const optCard = (a) => `<div class="rv-opt" data-id="${esc(a.id)}">
      <div class="rv-opt-th" ${a.thumb ? `style="background-image:url('${thumbUrl(a.thumb)}')"` : ""}>${a.kind === "audio" ? `<span class="wave">${a.category === "music" ? "♫" : "♪"}</span>` : ""}${a.duration_s ? `<span class="dur">${(+a.duration_s).toFixed(1)}s</span>` : ""}</div>
      <div class="rv-opt-t" title="${esc(a.description || "")}">${esc(a.title)}</div>
      <div class="row" style="gap:4px"><button class="btn small rv-opt-play">▶</button><button class="btn small primary rv-opt-use">Use this</button></div></div>`;
  async function openOptions(el, it) {
    const box = $(".rv-opts", el);
    if (!box.hidden) { box.hidden = true; return; }
    box.hidden = false;
    box.innerHTML = `<div class="muted" style="font-size:12px">Recommended for this moment${it.moments?.length ? ` (${it.moments.join(", ")})` : ""}:</div><div class="rv-opt-grid" id="og"></div>
      <div class="row" style="margin-top:6px"><input class="rv-q" type="search" placeholder="…or search any asset (e.g. sad violin, bruh, explosion)" style="flex:1"><button class="btn small rv-go">Search</button></div>`;
    const grid = $("#og", box);
    const fill = (list) => {
      grid.innerHTML = list.length ? list.map(optCard).join("") : `<div class="muted">No matches.</div>`;
      $$(".rv-opt", grid).forEach((o, i) => {
        const a = list[i];
        $(".rv-opt-play", o).onclick = (e) => playAssetBtn(a, e.target);
        $(".rv-opt-use", o).onclick = () => save(it.key, "change", { asset: a.id }, $(".rv-comment", el).value);
      });
    };
    const load = async (q) => {
      grid.innerHTML = `<div class="muted">Loading…</div>`;
      try {
        if (q) {
          const cats = { sfx: ["sfx_meme", "sfx_ui", "sfx_minecraft", "sfx_mlg", "sfx_laugh"], meme: ["meme_video"], greenscreen: ["green_screen"], music: ["music"], image: ["image", "brand_sticker"] }[it.kind] || [];
          const p = new URLSearchParams({ q, limit: 12 }); cats.forEach((c) => p.append("category", c)); ["clean", "mild"].forEach((r) => p.append("rating", r));
          fill((await api("/api/assets?" + p)).items);
        } else fill((await api(`/api/projects/${S}/review/options?key=${encodeURIComponent(it.key)}`)).options);
      } catch (e) { grid.innerHTML = `<div class="warn">${esc(e.message)}</div>`; }
    };
    $(".rv-go", box).onclick = () => load($(".rv-q", box).value.trim());
    $(".rv-q", box).addEventListener("keydown", (e) => { if (e.key === "Enter") load(e.target.value.trim()); });
    load("");
  }
  async function openEdit(el, it) {
    const box = $(".rv-opts", el);
    if (!box.hidden) { box.hidden = true; return; }
    box.hidden = false;
    const c = it.current || {};
    if (it.kind === "text") {
      box.innerHTML = `<div class="row"><input class="rv-txt" style="flex:1" value="${esc(c.text || "")}"><select class="rv-sty">${["impact", "minecraft", "label", "danger", "retro", "gta"].map((s) => `<option ${s === c.style ? "selected" : ""}>${s}</option>`).join("")}</select><button class="btn small primary rv-sv">Save</button></div>`;
      $(".rv-sv", box).onclick = () => save(it.key, "change", { text: $(".rv-txt", box).value, style: $(".rv-sty", box).value }, $(".rv-comment", el).value);
    } else {
      const tpls = (await api("/api/motion").catch(() => ({ templates: [] }))).templates;
      const vars = { ...(c.vars || {}) };
      box.innerHTML = `<div class="row"><span class="muted">Graphic</span><select class="rv-tpl">${tpls.map((t) => `<option ${t.name === c.template ? "selected" : ""}>${esc(t.name)}</option>`).join("")}</select></div>
        <div class="rv-vars">${Object.entries(vars).map(([k, v]) => `<label class="field" style="margin-top:4px">${esc(k)}<input data-var="${esc(k)}" value="${esc(typeof v === "object" ? JSON.stringify(v) : v)}"></label>`).join("") || `<div class="faint">(uses the template's defaults)</div>`}</div>
        <div class="row" style="margin-top:6px"><button class="btn small primary rv-sv">Save</button></div>`;
      $(".rv-sv", box).onclick = () => {
        const nv = {}; $$("[data-var]", box).forEach((i) => (nv[i.dataset.var] = i.value));
        save(it.key, "change", { template: $(".rv-tpl", box).value, vars: nv }, $(".rv-comment", el).value);
      };
    }
  }

  // ------------------------------------------------------------- side panel actions
  $("#rvKinds").onclick = (e) => {
    const k = e.target.closest(".rchip")?.dataset.k; if (!k) return;
    const i = F.kinds.indexOf(k); i >= 0 ? F.kinds.splice(i, 1) : F.kinds.push(k);
    store.set("rvfilter:" + slug, F); e.target.closest(".rchip").classList.toggle("on"); renderList();
  };
  $("#rvUnd").onclick = (e) => { F.undecided = !F.undecided; e.target.classList.toggle("on"); store.set("rvfilter:" + slug, F); renderList(); };
  $("#rvGeneral").addEventListener("change", (e) => api(`/api/projects/${S}/review/general`, { method: "POST", body: { note: e.target.value } }).then(() => toast("Saved")));
  $("#rvMd").onclick = async () => {
    const r = await api(`/api/projects/${S}/review/md`);
    $("#rvModal").innerHTML = `<div class="modal" style="display:flex"><div class="modal-box" style="max-width:900px"><div class="modal-head"><b>REVIEW.md</b><span class="spacer"></span><button class="btn small" id="mmClose">✕</button></div><pre style="padding:14px;max-height:70vh;overflow:auto;white-space:pre-wrap">${esc(r.markdown)}</pre></div></div>`;
    $("#mmClose").onclick = () => ($("#rvModal").innerHTML = "");
  };
  $("#rvApply").onclick = async () => {
    let j;
    try { j = await api(`/api/projects/${S}/review/apply`, { method: "POST", body: {} }); } catch (e) { return toast(e.message, true); }
    $("#rvApply").disabled = true;
    const tick = async () => {
      const r = await api("/api/jobs/" + j.id).catch(() => null); if (!r) return;
      const el = $("#rvJob"); if (!el) { clearInterval(iv); return; }
      el.textContent = `${r.status} · ${r.elapsed}s\n` + r.log.slice(-4).join("\n");
      if (r.status !== "running") {
        clearInterval(iv); toast(r.status === "done" ? "New preview ready" : "Rebuild " + r.status, r.status !== "done");
        $("#rvApply").disabled = false; if (r.status === "done") setTimeout(() => ReviewPage(H, slug), 400);
      }
    };
    const iv = setInterval(tick, 2000); pollers.push(iv); tick();
  };
  $("#rvAddOpen").onclick = () => openAdd();
  function openAdd() {
    const t = vid ? vid.currentTime : 0;
    $("#rvModal").innerHTML = `<div class="modal" style="display:flex"><div class="modal-box" style="max-width:760px"><div class="modal-head"><b>Add something at ${fmt(t)}</b><span class="spacer"></span><button class="btn small" id="mmClose">✕</button></div>
      <div style="padding:14px;display:grid;gap:10px">
        <div class="seg">${[["sfx", "Sound effect"], ["meme", "Meme clip"], ["greenscreen", "Green screen"], ["motion", "Motion graphic"], ["text", "Text"]].map(([k, l], i) => `<button class="btn ${i ? "" : "on"}" data-ak="${k}">${l}</button>`).join("")}</div>
        <div id="addBody"></div></div></div></div>`;
    $("#mmClose").onclick = () => ($("#rvModal").innerHTML = "");
    let kind = "sfx";
    const body = async () => {
      const b = $("#addBody");
      if (kind === "text") {
        b.innerHTML = `<div class="row"><input id="addTxt" style="flex:1" placeholder="Text to show"><select id="addSty">${["impact", "minecraft", "label", "danger", "retro", "gta"].map((s) => `<option>${s}</option>`).join("")}</select></div><input id="addCm" placeholder="Why? (comment)" style="width:100%;margin-top:6px"><button class="btn primary" id="addGo" style="margin-top:6px">Add text</button>`;
        $("#addGo").onclick = async () => { await api(`/api/projects/${S}/review/add`, { method: "POST", body: { kind: "text", out_time: t, text: $("#addTxt").value, style: $("#addSty").value, comment: $("#addCm").value, label: $("#addTxt").value } }); toast("Added (press Apply to see it)"); $("#rvModal").innerHTML = ""; };
      } else if (kind === "motion") {
        const tpls = (await api("/api/motion")).templates;
        b.innerHTML = `<div class="row"><select id="addTpl">${tpls.map((x) => `<option>${esc(x.name)}</option>`).join("")}</select><input id="addTxt" style="flex:1" placeholder="Main text (title / label / text var)"></div><input id="addCm" placeholder="Why? (comment)" style="width:100%;margin-top:6px"><button class="btn primary" id="addGo" style="margin-top:6px">Add graphic</button>`;
        $("#addGo").onclick = async () => { const tx = $("#addTxt").value; await api(`/api/projects/${S}/review/add`, { method: "POST", body: { kind: "motion", out_time: t, template: $("#addTpl").value, vars: tx ? { text: tx, title: tx, label: tx } : {}, comment: $("#addCm").value, label: $("#addTpl").value } }); toast("Added (press Apply to see it)"); $("#rvModal").innerHTML = ""; };
      } else {
        b.innerHTML = `<div class="row"><input id="addQ" type="search" style="flex:1" placeholder="Search ${kind === "sfx" ? "sounds" : kind === "meme" ? "memes" : "green screens"}…"><button class="btn" id="addSearch">Search</button></div><div class="rv-opt-grid" id="addGrid" style="margin-top:8px"></div><input id="addCm" placeholder="Why? (comment)" style="width:100%;margin-top:6px">`;
        const cats = { sfx: ["sfx_meme", "sfx_ui", "sfx_minecraft", "sfx_mlg", "sfx_laugh"], meme: ["meme_video"], greenscreen: ["green_screen"] }[kind];
        const go = async () => {
          const p = new URLSearchParams({ q: $("#addQ").value, limit: 18 }); cats.forEach((c) => p.append("category", c)); ["clean", "mild"].forEach((r) => p.append("rating", r));
          const list = (await api("/api/assets?" + p)).items;
          $("#addGrid").innerHTML = list.map(optCard).join("") || `<div class="muted">No matches</div>`;
          $$("#addGrid .rv-opt").forEach((o, i) => {
            $(".rv-opt-play", o).onclick = (e) => playAssetBtn(list[i], e.target);
            $(".rv-opt-use", o).onclick = async () => { await api(`/api/projects/${S}/review/add`, { method: "POST", body: { kind, out_time: t, asset: list[i].id, comment: $("#addCm").value } }); toast("Added (press Apply to see it)"); $("#rvModal").innerHTML = ""; };
          });
        };
        $("#addSearch").onclick = go; $("#addQ").addEventListener("keydown", (e) => { if (e.key === "Enter") go(); });
        go();
      }
    };
    $$("[data-ak]").forEach((bt) => (bt.onclick = () => { $$("[data-ak]").forEach((x) => x.classList.remove("on")); bt.classList.add("on"); kind = bt.dataset.ak; body(); }));
    body();
  }

  renderList();
}

toolu_01PZQmCys4P27vatRwZ3khdg.content:
// Review & training page: full editor timeline + every edit decision (approve / swap / remove / comment) with a live preview.
// Answers are saved per episode and logged to studio/learning (the finder learns from them). "Apply" rebuilds the edit and
// re-renders the preview. Helpers come from app.js through `H`.
export async function ReviewPage(H, slug) {
  const { $, $$, api, toast, esc, fmt, view, packUrl, thumbUrl, pollers, store } = H;
  const S = encodeURIComponent(slug);
  let data;
  try { data = await api(`/api/projects/${S}/review`); } catch (e) { view.innerHTML = `<div class="empty">${esc(e.message)}</div>`; return; }
  let tl = { duration: 0, tracks: {}, warnings: [] };
  try { tl = await api(`/api/projects/${S}/timeline`); } catch {}
  const KINDS = [["scene", "Scenes"], ["cinematic", "Drone / replay shots"], ["music", "Music"], ["meme", "Memes"], ["greenscreen", "Green screens"],
    ["motion", "Motion graphics"], ["text", "Text"], ["sfx", "Sound effects"], ["bleep", "Bleeps"], ["image", "Images"], ["added", "Added by you"]];
  const KCOLOR = { scene: "#6fbf4f", cinematic: "#4fb3ab", music: "#6f86d8", meme: "#b07fd8", greenscreen: "#d48a3a", motion: "#4fb3ab", text: "#d4b040", sfx: "#d46060", bleep: "#999", image: "#4fb3ab", added: "#ffcc33" };
  const dec = data.decisions;
  const F = store.get("rvfilter:" + slug, { kinds: ["scene", "cinematic", "music", "meme", "greenscreen", "motion", "text"], undecided: false });
  const items = data.items;
  const byRef = {};
  items.forEach((it) => { if (it.ref) byRef[it.ref.join(":")] = it; });
  const statusOf = (it) => (dec.items[it.key] || {}).status || "";
  const prev = data.preview;
  const vurl = prev ? `/media/project/${S}/out/${encodeURIComponent(prev.name)}?v=${Math.round(prev.mtime)}` : "";

  view.innerHTML = `
    <div class="row"><div><h1>Review &amp; train: ${esc(slug)}</h1>
      <p class="sub">Every choice in this edit. Keep it, swap it for a recommendation (or search anything), remove it, or just leave a comment. Your answers rebuild this video and teach the auto-editor for the next one.</p></div></div>
    ${prev && prev.stale ? `<div class="card warn" style="margin-bottom:10px">The preview video is older than the current edit. Press <b>Apply &amp; re-render preview</b> to refresh it.</div>` : ""}
    <div class="rv-top">
      <div class="rv-player">${prev ? `<video id="rvVid" controls src="${vurl}"></video>` : `<div class="empty">No preview render yet. Press Apply &amp; re-render.</div>`}
        <div class="faint" id="rvNow" style="font-size:12px;margin-top:4px">${prev ? esc(prev.name) : ""}</div></div>
      <div class="rv-side card">
        <div class="row"><b>${items.length}</b> decisions · <b id="rvDone">0</b> answered <span class="spacer"></span>
          <button class="btn gold" id="rvApply">Apply &amp; re-render preview</button></div>
        <div class="rv-prog"><div id="rvBar"></div></div>
        <div id="rvJob" class="muted mono" style="font-size:11px;white-space:pre-wrap"></div>
        <div class="rv-chips" id="rvKinds">${KINDS.map(([k, l]) => `<span class="rchip ${F.kinds.includes(k) ? "on" : ""}" data-k="${k}">${l} <i>${items.filter((i) => i.kind === k).length}</i></span>`).join("")}</div>
        <label class="rchip ${F.undecided ? "on" : ""}" id="rvUnd">only show unanswered</label>
        <textarea id="rvGeneral" rows="3" placeholder="Overall comments for this video (pacing, what felt random, what you loved)…">${esc(dec.general || "")}</textarea>
        <div class="row"><button class="btn small" id="rvMd">Open REVIEW.md</button>
          <button class="btn small" id="rvAddOpen">＋ Add something at the current time</button></div>
        <div class="faint" style="font-size:11px">Learned so far: ${data.summary.answers} answers${data.summary.liked.length ? ` · likes ${data.summary.liked.slice(0, 3).map((x) => esc(x[0].replace(/^.*\./, ""))).join(", ")}` : ""}</div>
      </div>
    </div>
    <h2 style="margin:16px 0 6px">Timeline <span class="muted" style="font-size:12px;font-weight:400">every split clip and edit · click a block to jump there and open its card · ${fmt(tl.duration)} total</span></h2>
    <div class="row" style="margin-bottom:4px"><span class="muted" style="font-size:12px">zoom</span><input type="range" id="rvZoom" min="3" max="120" value="${store.get("rvzoom", 14)}"><span class="spacer"></span>
      <span class="muted" id="rvClip" style="font-size:12px"></span></div>
    <div class="tl" id="rvTl"></div>
    <div id="rvList" style="margin-top:14px"></div>
    <div id="rvModal"></div>`;

  const vid = $("#rvVid");
  const refresh = () => {
    const n = items.filter((i) => statusOf(i)).length;
    $("#rvDone").textContent = n;
    $("#rvBar").style.width = Math.round((100 * n) / Math.max(1, items.length)) + "%";
  };
  const seek = (t, play = true, until = null) => {
    if (!vid) return;
    vid.currentTime = Math.max(0, t);
    if (play) vid.play().catch(() => {});
    clearTimeout(seek._t);
    if (until) seek._t = setTimeout(() => vid.pause(), Math.max(500, (until - t) * 1000));
  };

  // ------------------------------------------------------------- timeline
  const TRACKS = [["scenes", "Scenes"], ["segments", "Video clips"], ["zooms", "Zoom/shake"], ["overlays", "Overlays"], ["text", "Text"], ["sfx", "SFX"], ["music", "Music"], ["bleeps", "Bleeps"]];
  tl.tracks.scenes = items.filter((i) => i.kind === "scene").map((i) => ({ ...i, label: i.title.replace("Scene: ", ""), _item: i }));
  const drawTl = (pps) => {
    const W = Math.max(tl.duration * pps, 300);
    const step = pps > 40 ? 5 : pps > 14 ? 15 : pps > 6 ? 30 : 60;
    let ruler = "";
    for (let t = 0; t <= tl.duration; t += step) ruler += `<span style="left:${t * pps}px">${fmt(t).replace(/\.\d$/, "")}</span>`;
    const refKey = { sfx: "audio.sfx", overlays: "overlays", text: "text", music: "audio.music", bleeps: "audio.bleeps" };
    $("#rvTl").innerHTML = `<div class="tl-inner" style="width:${W + 84}px"><div class="tl-ruler" style="width:${W}px">${ruler}</div>
      ${TRACKS.filter(([k]) => (tl.tracks[k] || []).length).map(([k, name]) => `<div class="tl-track"><div class="tl-name">${name}</div><div class="tl-lane">
        ${tl.tracks[k].map((it, i) => {
          let item = it._item, cls = "ti-" + k;
          if (k === "segments") cls = "ti-" + it.type;
          if (!item && refKey[k]) item = byRef[refKey[k] + ":" + it.k];
          if (k === "segments" && it.type === "cutaway") item = byRef["segments:" + it.i];
          const st = item ? statusOf(item) : "";
          return `<div class="tl-item ${cls} ${st ? "st-" + st : ""}" data-k="${k}" data-i="${i}" style="left:${it.start * pps}px;width:${Math.max(3, (it.end - it.start) * pps - 1)}px" title="${esc(it.label)}  ${fmt(it.start)}–${fmt(it.end)}">${esc(it.label)}</div>`;
        }).join("")}</div></div>`).join("")}<div class="tl-head" id="rvHead" style="left:84px"></div></div>`;
    $$("#rvTl .tl-item").forEach((b) => (b.onclick = (e) => {
      e.stopPropagation();
      const k = b.dataset.k, it = tl.tracks[k][b.dataset.i];
      seek(it.start - 1.2, true, it.end + 1.0);
      $("#rvClip").textContent = `${k}: ${it.label} · ${fmt(it.start)}–${fmt(it.end)}` +
        (it.src_in != null ? ` · source ${fmt(it.src_in)}→${fmt(it.src_out)}${it.speed !== 1 ? ` @${it.speed}×` : ""}` : "");
      let item = it._item;
      const rk = { sfx: "audio.sfx", overlays: "overlays", text: "text", music: "audio.music", bleeps: "audio.bleeps" }[k];
      if (!item && rk) item = byRef[rk + ":" + it.k];
      if (k === "segments" && it.type === "cutaway") item = byRef["segments:" + it.i];
      if (item) openCard(item.key);
    }));
    $("#rvTl .tl-inner").onclick = (e) => { const r = $("#rvTl .tl-inner").getBoundingClientRect(); seek(Math.max(0, (e.clientX - r.left - 84) / pps), false); };
    drawTl._pps = pps;
  };
  drawTl(store.get("rvzoom", 14));
  $("#rvZoom").oninput = (e) => { store.set("rvzoom", +e.target.value); drawTl(+e.target.value); };
  vid?.addEventListener("timeupdate", () => { const h = $("#rvHead"); if (h) h.style.left = 84 + vid.currentTime * drawTl._pps + "px"; });

  // ------------------------------------------------------------- cards
  function cardHtml(it) {
    const d = dec.items[it.key] || {};
    const c = it.current || {};
    const st = d.status || "";
    const cur = c.asset ? `<span class="mono">${esc(c.asset)}</span>` : c.template ? `<span class="mono">${esc(c.template)}</span>` : c.text != null ? `“${esc(c.text)}”` : "";
    const chosen = d.status === "change" && d.choice ? `<div class="rv-chosen">→ you chose: <b>${esc(d.choice.asset || d.choice.template || d.choice.text || "")}</b></div>` : "";
    return `<div class="rv-card ${st ? "st-" + st : ""}" id="c-${cssId(it.key)}" data-key="${esc(it.key)}">
      <div class="rv-head"><span class="rv-time" data-t="${it.start}" data-e="${it.end}">▶ ${fmt(it.start)}</span>
        <span class="rv-kind" style="background:${KCOLOR[it.kind] || "#666"}33;border-color:${KCOLOR[it.kind] || "#666"}">${it.kind}</span>
        <b class="rv-title">${esc(it.title)}</b><span class="spacer"></span><span class="rv-st">${st ? { keep: "✓ kept", change: "✎ changed", remove: "✕ removed", comment: "💬" }[st] || st : ""}</span></div>
      ${it.context ? `<div class="rv-ctx">he says: “${esc(it.context)}”</div>` : ""}
      <div class="rv-cur">now: ${cur} ${c.asset && ["sfx", "meme", "greenscreen", "music", "image"].includes(it.kind) ? `<button class="btn small rv-listen">▶ preview asset</button>` : ""}</div>
      ${chosen}
      <div class="rv-actions">
        ${it.kind === "added" ? "" : `<button class="btn small rv-keep ${st === "keep" ? "on" : ""}">✓ Keep</button>`}
        ${["sfx", "meme", "greenscreen", "music", "image", "added"].includes(it.kind) ? `<button class="btn small rv-change">✎ Swap…</button>` : ""}
        ${it.kind === "motion" || it.kind === "text" ? `<button class="btn small rv-edit">✎ Edit…</button>` : ""}
        <button class="btn small danger rv-remove ${st === "remove" ? "on" : ""}">✕ ${it.kind === "scene" ? "Cut this scene" : "Remove"}</button>
        <input class="rv-comment" placeholder="Comment (why / what you'd rather see)…" value="${esc(d.comment || "")}"></div>
      <div class="rv-opts" hidden></div></div>`;
  }
  const cssId = (k) => k.replace(/[^a-zA-Z0-9]/g, "_");
  function renderList() {
    const vis = items.filter((i) => F.kinds.includes(i.kind) && (!F.undecided || !statusOf(i)));
    $("#rvList").innerHTML = vis.length ? vis.map(cardHtml).join("") : `<div class="empty">Nothing to show with these filters.</div>`;
    $$("#rvList .rv-card").forEach(wireCard);
    refresh();
  }
  const itemOf = (key) => items.find((i) => i.key === key);
  async function save(key, status, choice, comment) {
    const d = await api(`/api/projects/${S}/review/decision`, { method: "POST", body: { key, status, choice: choice || null, comment: comment ?? "" } });
    dec.items[key] = d;
    const it = itemOf(key), el = $("#c-" + cssId(key));
    if (el) { el.outerHTML = cardHtml(it); wireCard($("#c-" + cssId(key))); }
    drawTl(drawTl._pps);
    refresh();
  }
  function wireCard(el) {
    const key = el.dataset.key, it = itemOf(key);
    const comment = () => $(".rv-comment", el).value;
    $(".rv-time", el).onclick = () => seek(it.start - 1.5, true, it.end + 1.0);
    $(".rv-keep", el)?.addEventListener("click", () => save(key, "keep", null, comment()));
    $(".rv-remove", el).addEventListener("click", () => save(key, "remove", null, comment()));
    $(".rv-comment", el).addEventListener("change", () => save(key, statusOf(it) || "comment", (dec.items[key] || {}).choice, comment()));
    $(".rv-listen", el)?.addEventListener("click", async (e) => {
      const a = await api("/api/assets/" + encodeURIComponent(it.current.asset)).catch(() => null);
      if (a) playAssetBtn(a, e.target);
    });
    $(".rv-change", el)?.addEventListener("click", () => openOptions(el, it));
    $(".rv-edit", el)?.addEventListener("click", () => openEdit(el, it));
  }
  function openCard(key) {
    const it = itemOf(key);
    if (!it) return;
    if (!F.kinds.includes(it.kind)) { F.kinds.push(it.kind); store.set("rvfilter:" + slug, F); $$("#rvKinds .rchip").forEach((c) => c.classList.toggle("on", F.kinds.includes(c.dataset.k))); renderList(); }
    const el = $("#c-" + cssId(key));
    if (el) { el.scrollIntoView({ behavior: "smooth", block: "center" }); el.classList.add("flash"); setTimeout(() => el.classList.remove("flash"), 1600); }
  }
  function playAssetBtn(a, btn) {
    const p = $("#player");
    if (!p.paused && p.dataset.id === a.id) { p.pause(); btn.textContent = "▶ preview asset"; return; }
    p.src = packUrl(a.path, a.root); p.dataset.id = a.id; p.currentTime = 0;
    p.play().then(() => (btn.textContent = "❚❚ stop")).catch(() => toast("Can't play this in the browser", true));
    p.onended = () => (btn.textContent = "▶ preview asset");
  }
  const optCard = (a) => `<div class="rv-opt" data-id="${esc(a.id)}">
      <div class="rv-opt-th" ${a.thumb ? `style="background-image:url('${thumbUrl(a.thumb)}')"` : ""}>${a.kind === "audio" ? `<span class="wave">${a.category === "music" ? "♫" : "♪"}</span>` : ""}${a.duration_s ? `<span class="dur">${(+a.duration_s).toFixed(1)}s</span>` : ""}</div>
      <div class="rv-opt-t" title="${esc(a.description || "")}">${esc(a.title)}</div>
      <div class="row" style="gap:4px"><button class="btn small rv-opt-play">▶</button><button class="btn small primary rv-opt-use">Use this</button></div></div>`;
  async function openOptions(el, it) {
    const box = $(".rv-opts", el);
    if (!box.hidden) { box.hidden = true; return; }
    box.hidden = false;
    box.innerHTML = `<div class="muted" style="font-size:12px">Recommended for this moment${it.moments?.length ? ` (${it.moments.join(", ")})` : ""}:</div><div class="rv-opt-grid" id="og"></div>
      <div class="row" style="margin-top:6px"><input class="rv-q" type="search" placeholder="…or search any asset (e.g. sad violin, bruh, explosion)" style="flex:1"><button class="btn small rv-go">Search</button></div>`;
    const grid = $("#og", box);
    const fill = (list) => {
      grid.innerHTML = list.length ? list.map(optCard).join("") : `<div class="muted">No matches.</div>`;
      $$(".rv-opt", grid).forEach((o, i) => {
        const a = list[i];
        $(".rv-opt-play", o).onclick = (e) => playAssetBtn(a, e.target);
        $(".rv-opt-use", o).onclick = () => save(it.key, "change", { asset: a.id }, $(".rv-comment", el).value);
      });
    };
    const load = async (q) => {
      grid.innerHTML = `<div class="muted">Loading…</div>`;
      try {
        if (q) {
          const cats = { sfx: ["sfx_meme", "sfx_ui", "sfx_minecraft", "sfx_mlg", "sfx_laugh"], meme: ["meme_video"], greenscreen: ["green_screen"], music: ["music"], image: ["image", "brand_sticker"] }[it.kind] || [];
          const p = new URLSearchParams({ q, limit: 12 }); cats.forEach((c) => p.append("category", c)); ["clean", "mild"].forEach((r) => p.append("rating", r));
          fill((await api("/api/assets?" + p)).items);
        } else fill((await api(`/api/projects/${S}/review/options?key=${encodeURIComponent(it.key)}`)).options);
      } catch (e) { grid.innerHTML = `<div class="warn">${esc(e.message)}</div>`; }
    };
    $(".rv-go", box).onclick = () => load($(".rv-q", box).value.trim());
    $(".rv-q", box).addEventListener("keydown", (e) => { if (e.key === "Enter") load(e.target.value.trim()); });
    load("");
  }
  async function openEdit(el, it) {
    const box = $(".rv-opts", el);
    if (!box.hidden) { box.hidden = true; return; }
    box.hidden = false;
    const c = it.current || {};
    if (it.kind === "text") {
      box.innerHTML = `<div class="row"><input class="rv-txt" style="flex:1" value="${esc(c.text || "")}"><select class="rv-sty">${["impact", "minecraft", "label", "danger", "retro", "gta"].map((s) => `<option ${s === c.style ? "selected" : ""}>${s}</option>`).join("")}</select><button class="btn small primary rv-sv">Save</button></div>`;
      $(".rv-sv", box).onclick = () => save(it.key, "change", { text: $(".rv-txt", box).value, style: $(".rv-sty", box).value }, $(".rv-comment", el).value);
    } else {
      const tpls = (await api("/api/motion").catch(() => ({ templates: [] }))).templates;
      const vars = { ...(c.vars || {}) };
      box.innerHTML = `<div class="row"><span class="muted">Graphic</span><select class="rv-tpl">${tpls.map((t) => `<option ${t.name === c.template ? "selected" : ""}>${esc(t.name)}</option>`).join("")}</select></div>
        <div class="rv-vars">${Object.entries(vars).map(([k, v]) => `<label class="field" style="margin-top:4px">${esc(k)}<input data-var="${esc(k)}" value="${esc(typeof v === "object" ? JSON.stringify(v) : v)}"></label>`).join("") || `<div class="faint">(uses the template's defaults)</div>`}</div>
        <div class="row" style="margin-top:6px"><button class="btn small primary rv-sv">Save</button></div>`;
      $(".rv-sv", box).onclick = () => {
        const nv = {}; $$("[data-var]", box).forEach((i) => (nv[i.dataset.var] = i.value));
        save(it.key, "change", { template: $(".rv-tpl", box).value, vars: nv }, $(".rv-comment", el).value);
      };
    }
  }

  // ------------------------------------------------------------- side panel actions
  $("#rvKinds").onclick = (e) => {
    const k = e.target.closest(".rchip")?.dataset.k; if (!k) return;
    const i = F.kinds.indexOf(k); i >= 0 ? F.kinds.splice(i, 1) : F.kinds.push(k);
    store.set("rvfilter:" + slug, F); e.target.closest(".rchip").classList.toggle("on"); renderList();
  };
  $("#rvUnd").onclick = (e) => { F.undecided = !F.undecided; e.target.classList.toggle("on"); store.set("rvfilter:" + slug, F); renderList(); };
  $("#rvGeneral").addEventListener("change", (e) => api(`/api/projects/${S}/review/general`, { method: "POST", body: { note: e.target.value } }).then(() => toast("Saved")));
  $("#rvMd").onclick = async () => {
    const r = await api(`/api/projects/${S}/review/md`);
    $("#rvModal").innerHTML = `<div class="modal" style="display:flex"><div class="modal-box" style="max-width:900px"><div class="modal-head"><b>REVIEW.md</b><span class="spacer"></span><button class="btn small" id="mmClose">✕</button></div><pre style="padding:14px;max-height:70vh;overflow:auto;white-space:pre-wrap">${esc(r.markdown)}</pre></div></div>`;
    $("#mmClose").onclick = () => ($("#rvModal").innerHTML = "");
  };
  $("#rvApply").onclick = async () => {
    let j;
    try { j = await api(`/api/projects/${S}/review/apply`, { method: "POST", body: {} }); } catch (e) { return toast(e.message, true); }
    $("#rvApply").disabled = true;
    const tick = async () => {
      const r = await api("/api/jobs/" + j.id).catch(() => null); if (!r) return;
      const el = $("#rvJob"); if (!el) { clearInterval(iv); return; }
      el.textContent = `${r.status} · ${r.elapsed}s\n` + r.log.slice(-4).join("\n");
      if (r.status !== "running") {
        clearInterval(iv); toast(r.status === "done" ? "New preview ready" : "Rebuild " + r.status, r.status !== "done");
        $("#rvApply").disabled = false; if (r.status === "done") setTimeout(() => ReviewPage(H, slug), 400);
      }
    };
    const iv = setInterval(tick, 2000); pollers.push(iv); tick();
  };
  $("#rvAddOpen").onclick = () => openAdd();
  function openAdd() {
    const t = vid ? vid.currentTime : 0;
    $("#rvModal").innerHTML = `<div class="modal" style="display:flex"><div class="modal-box" style="max-width:760px"><div class="modal-head"><b>Add something at ${fmt(t)}</b><span class="spacer"></span><button class="btn small" id="mmClose">✕</button></div>
      <div style="padding:14px;display:grid;gap:10px">
        <div class="seg">${[["sfx", "Sound effect"], ["meme", "Meme clip"], ["greenscreen", "Green screen"], ["motion", "Motion graphic"], ["text", "Text"]].map(([k, l], i) => `<button class="btn ${i ? "" : "on"}" data-ak="${k}">${l}</button>`).join("")}</div>
        <div id="addBody"></div></div></div></div>`;
    $("#mmClose").onclick = () => ($("#rvModal").innerHTML = "");
    let kind = "sfx";
    const body = async () => {
      const b = $("#addBody");
      if (kind === "text") {
        b.innerHTML = `<div class="row"><input id="addTxt" style="flex:1" placeholder="Text to show"><select id="addSty">${["impact", "minecraft", "label", "danger", "retro", "gta"].map((s) => `<option>${s}</option>`).join("")}</select></div><input id="addCm" placeholder="Why? (comment)" style="width:100%;margin-top:6px"><button class="btn primary" id="addGo" style="margin-top:6px">Add text</button>`;
        $("#addGo").onclick = async () => { await api(`/api/projects/${S}/review/add`, { method: "POST", body: { kind: "text", out_time: t, text: $("#addTxt").value, style: $("#addSty").value, comment: $("#addCm").value, label: $("#addTxt").value } }); toast("Added (press Apply to see it)"); $("#rvModal").innerHTML = ""; };
      } else if (kind === "motion") {
        const tpls = (await api("/api/motion")).templates;
        b.innerHTML = `<div class="row"><select id="addTpl">${tpls.map((x) => `<option>${esc(x.name)}</option>`).join("")}</select><input id="addTxt" style="flex:1" placeholder="Main text (title / label / text var)"></div><input id="addCm" placeholder="Why? (comment)" style="width:100%;margin-top:6px"><button class="btn primary" id="addGo" style="margin-top:6px">Add graphic</button>`;
        $("#addGo").onclick = async () => { const tx = $("#addTxt").value; await api(`/api/projects/${S}/review/add`, { method: "POST", body: { kind: "motion", out_time: t, template: $("#addTpl").value, vars: tx ? { text: tx, title: tx, label: tx } : {}, comment: $("#addCm").value, label: $("#addTpl").value } }); toast("Added (press Apply to see it)"); $("#rvModal").innerHTML = ""; };
      } else {
        b.innerHTML = `<div class="row"><input id="addQ" type="search" style="flex:1" placeholder="Search ${kind === "sfx" ? "sounds" : kind === "meme" ? "memes" : "green screens"}…"><button class="btn" id="addSearch">Search</button></div><div class="rv-opt-grid" id="addGrid" style="margin-top:8px"></div><input id="addCm" placeholder="Why? (comment)" style="width:100%;margin-top:6px">`;
        const cats = { sfx: ["sfx_meme", "sfx_ui", "sfx_minecraft", "sfx_mlg", "sfx_laugh"], meme: ["meme_video"], greenscreen: ["green_screen"] }[kind];
        const go = async () => {
          const p = new URLSearchParams({ q: $("#addQ").value, limit: 18 }); cats.forEach((c) => p.append("category", c)); ["clean", "mild"].forEach((r) => p.append("rating", r));
          const list = (await api("/api/assets?" + p)).items;
          $("#addGrid").innerHTML = list.map(optCard).join("") || `<div class="muted">No matches</div>`;
          $$("#addGrid .rv-opt").forEach((o, i) => {
            $(".rv-opt-play", o).onclick = (e) => playAssetBtn(list[i], e.target);
            $(".rv-opt-use", o).onclick = async () => { await api(`/api/projects/${S}/review/add`, { method: "POST", body: { kind, out_time: t, asset: list[i].id, comment: $("#addCm").value } }); toast("Added (press Apply to see it)"); $("#rvModal").innerHTML = ""; };
          });
        };
        $("#addSearch").onclick = go; $("#addQ").addEventListener("keydown", (e) => { if (e.key === "Enter") go(); });
        go();
      }
    };
    $$("[data-ak]").forEach((bt) => (bt.onclick = () => { $$("[data-ak]").forEach((x) => x.classList.remove("on")); bt.classList.add("on"); kind = bt.dataset.ak; body(); }));
    body();
  }

  renderList();
}

toolUseResult.content:
// Review & training page: full editor timeline + every edit decision (approve / swap / remove / comment) with a live preview.
// Answers are saved per episode and logged to studio/learning (the finder learns from them). "Apply" rebuilds the edit and
// re-renders the preview. Helpers come from app.js through `H`.
export async function ReviewPage(H, slug) {
  const { $, $$, api, toast, esc, fmt, view, packUrl, thumbUrl, pollers, store } = H;
  const S = encodeURIComponent(slug);
  let data;
  try { data = await api(`/api/projects/${S}/review`); } catch (e) { view.innerHTML = `<div class="empty">${esc(e.message)}</div>`; return; }
  let tl = { duration: 0, tracks: {}, warnings: [] };
  try { tl = await api(`/api/projects/${S}/timeline`); } catch {}
  const KINDS = [["scene", "Scenes"], ["cinematic", "Drone / replay shots"], ["music", "Music"], ["meme", "Memes"], ["greenscreen", "Green screens"],
    ["motion", "Motion graphics"], ["text", "Text"], ["sfx", "Sound effects"], ["bleep", "Bleeps"], ["image", "Images"], ["added", "Added by you"]];
  const KCOLOR = { scene: "#6fbf4f", cinematic: "#4fb3ab", music: "#6f86d8", meme: "#b07fd8", greenscreen: "#d48a3a", motion: "#4fb3ab", text: "#d4b040", sfx: "#d46060", bleep: "#999", image: "#4fb3ab", added: "#ffcc33" };
  const dec = data.decisions;
  const F = store.get("rvfilter:" + slug, { kinds: ["scene", "cinematic", "music", "meme", "greenscreen", "motion", "text"], undecided: false });
  const items = data.items;
  const byRef = {};
  items.forEach((it) => { if (it.ref) byRef[it.ref.join(":")] = it; });
  const statusOf = (it) => (dec.items[it.key] || {}).status || "";
  const prev = data.preview;
  const vurl = prev ? `/media/project/${S}/out/${encodeURIComponent(prev.name)}?v=${Math.round(prev.mtime)}` : "";

  view.innerHTML = `
    <div class="row"><div><h1>Review &amp; train: ${esc(slug)}</h1>
      <p class="sub">Every choice in this edit. Keep it, swap it for a recommendation (or search anything), remove it, or just leave a comment. Your answers rebuild this video and teach the auto-editor for the next one.</p></div></div>
    ${prev && prev.stale ? `<div class="card warn" style="margin-bottom:10px">The preview video is older than the current edit. Press <b>Apply &amp; re-render preview</b> to refresh it.</div>` : ""}
    <div class="rv-top">
      <div class="rv-player">${prev ? `<video id="rvVid" controls src="${vurl}"></video>` : `<div class="empty">No preview render yet. Press Apply &amp; re-render.</div>`}
        <div class="faint" id="rvNow" style="font-size:12px;margin-top:4px">${prev ? esc(prev.name) : ""}</div></div>
      <div class="rv-side card">
        <div class="row"><b>${items.length}</b> decisions · <b id="rvDone">0</b> answered <span class="spacer"></span>
          <button class="btn gold" id="rvApply">Apply &amp; re-render preview</button></div>
        <div class="rv-prog"><div id="rvBar"></div></div>
        <div id="rvJob" class="muted mono" style="font-size:11px;white-space:pre-wrap"></div>
        <div class="rv-chips" id="rvKinds">${KINDS.map(([k, l]) => `<span class="rchip ${F.kinds.includes(k) ? "on" : ""}" data-k="${k}">${l} <i>${items.filter((i) => i.kind === k).length}</i></span>`).join("")}</div>
        <label class="rchip ${F.undecided ? "on" : ""}" id="rvUnd">only show unanswered</label>
        <textarea id="rvGeneral" rows="3" placeholder="Overall comments for this video (pacing, what felt random, what you loved)…">${esc(dec.general || "")}</textarea>
        <div class="row"><button class="btn small" id="rvMd">Open REVIEW.md</button>
          <button class="btn small" id="rvAddOpen">＋ Add something at the current time</button></div>
        <div class="faint" style="font-size:11px">Learned so far: ${data.summary.answers} answers${data.summary.liked.length ? ` · likes ${data.summary.liked.slice(0, 3).map((x) => esc(x[0].replace(/^.*\./, ""))).join(", ")}` : ""}</div>
      </div>
    </div>
    <h2 style="margin:16px 0 6px">Timeline <span class="muted" style="font-size:12px;font-weight:400">every split clip and edit · click a block to jump there and open its card · ${fmt(tl.duration)} total</span></h2>
    <div class="row" style="margin-bottom:4px"><span class="muted" style="font-size:12px">zoom</span><input type="range" id="rvZoom" min="3" max="120" value="${store.get("rvzoom", 14)}"><span class="spacer"></span>
      <span class="muted" id="rvClip" style="font-size:12px"></span></div>
    <div class="tl" id="rvTl"></div>
    <div id="rvList" style="margin-top:14px"></div>
    <div id="rvModal"></div>`;

  const vid = $("#rvVid");
  const refresh = () => {
    const n = items.filter((i) => statusOf(i)).length;
    $("#rvDone").textContent = n;
    $("#rvBar").style.width = Math.round((100 * n) / Math.max(1, items.length)) + "%";
  };
  const seek = (t, play = true, until = null) => {
    if (!vid) return;
    vid.currentTime = Math.max(0, t);
    if (play) vid.play().catch(() => {});
    clearTimeout(seek._t);
    if (until) seek._t = setTimeout(() => vid.pause(), Math.max(500, (until - t) * 1000));
  };

  // ------------------------------------------------------------- timeline
  const TRACKS = [["scenes", "Scenes"], ["segments", "Video clips"], ["zooms", "Zoom/shake"], ["overlays", "Overlays"], ["text", "Text"], ["sfx", "SFX"], ["music", "Music"], ["bleeps", "Bleeps"]];
  tl.tracks.scenes = items.filter((i) => i.kind === "scene").map((i) => ({ ...i, label: i.title.replace("Scene: ", ""), _item: i }));
  const drawTl = (pps) => {
    const W = Math.max(tl.duration * pps, 300);
    const step = pps > 40 ? 5 : pps > 14 ? 15 : pps > 6 ? 30 : 60;
    let ruler = "";
    for (let t = 0; t <= tl.duration; t += step) ruler += `<span style="left:${t * pps}px">${fmt(t).replace(/\.\d$/, "")}</span>`;
    const refKey = { sfx: "audio.sfx", overlays: "overlays", text: "text", music: "audio.music", bleeps: "audio.bleeps" };
    $("#rvTl").innerHTML = `<div class="tl-inner" style="width:${W + 84}px"><div class="tl-ruler" style="width:${W}px">${ruler}</div>
      ${TRACKS.filter(([k]) => (tl.tracks[k] || []).length).map(([k, name]) => `<div class="tl-track"><div class="tl-name">${name}</div><div class="tl-lane">
        ${tl.tracks[k].map((it, i) => {
          let item = it._item, cls = "ti-" + k;
          if (k === "segments") cls = "ti-" + it.type;
          if (!item && refKey[k]) item = byRef[refKey[k] + ":" + it.k];
          if (k === "segments" && it.type === "cutaway") item = byRef["segments:" + it.i];
          const st = item ? statusOf(item) : "";
          return `<div class="tl-item ${cls} ${st ? "st-" + st : ""}" data-k="${k}" data-i="${i}" style="left:${it.start * pps}px;width:${Math.max(3, (it.end - it.start) * pps - 1)}px" title="${esc(it.label)}  ${fmt(it.start)}–${fmt(it.end)}">${esc(it.label)}</div>`;
        }).join("")}</div></div>`).join("")}<div class="tl-head" id="rvHead" style="left:84px"></div></div>`;
    $$("#rvTl .tl-item").forEach((b) => (b.onclick = (e) => {
      e.stopPropagation();
      const k = b.dataset.k, it = tl.tracks[k][b.dataset.i];
      seek(it.start - 1.2, true, it.end + 1.0);
      $("#rvClip").textContent = `${k}: ${it.label} · ${fmt(it.start)}–${fmt(it.end)}` +
        (it.src_in != null ? ` · source ${fmt(it.src_in)}→${fmt(it.src_out)}${it.speed !== 1 ? ` @${it.speed}×` : ""}` : "");
      let item = it._item;
      const rk = { sfx: "audio.sfx", overlays: "overlays", text: "text", music: "audio.music", bleeps: "audio.bleeps" }[k];
      if (!item && rk) item = byRef[rk + ":" + it.k];
      if (k === "segments" && it.type === "cutaway") item = byRef["segments:" + it.i];
      if (item) openCard(item.key);
    }));
    $("#rvTl .tl-inner").onclick = (e) => { const r = $("#rvTl .tl-inner").getBoundingClientRect(); seek(Math.max(0, (e.clientX - r.left - 84) / pps), false); };
    drawTl._pps = pps;
  };
  drawTl(store.get("rvzoom", 14));
  $("#rvZoom").oninput = (e) => { store.set("rvzoom", +e.target.value); drawTl(+e.target.value); };
  vid?.addEventListener("timeupdate", () => { const h = $("#rvHead"); if (h) h.style.left = 84 + vid.currentTime * drawTl._pps + "px"; });

  // ------------------------------------------------------------- cards
  function cardHtml(it) {
    const d = dec.items[it.key] || {};
    const c = it.current || {};
    const st = d.status || "";
    const cur = c.asset ? `<span class="mono">${esc(c.asset)}</span>` : c.template ? `<span class="mono">${esc(c.template)}</span>` : c.text != null ? `“${esc(c.text)}”` : "";
    const chosen = d.status === "change" && d.choice ? `<div class="rv-chosen">→ you chose: <b>${esc(d.choice.asset || d.choice.template || d.choice.text || "")}</b></div>` : "";
    return `<div class="rv-card ${st ? "st-" + st : ""}" id="c-${cssId(it.key)}" data-key="${esc(it.key)}">
      <div class="rv-head"><span class="rv-time" data-t="${it.start}" data-e="${it.end}">▶ ${fmt(it.start)}</span>
        <span class="rv-kind" style="background:${KCOLOR[it.kind] || "#666"}33;border-color:${KCOLOR[it.kind] || "#666"}">${it.kind}</span>
        <b class="rv-title">${esc(it.title)}</b><span class="spacer"></span><span class="rv-st">${st ? { keep: "✓ kept", change: "✎ changed", remove: "✕ removed", comment: "💬" }[st] || st : ""}</span></div>
      ${it.context ? `<div class="rv-ctx">he says: “${esc(it.context)}”</div>` : ""}
      <div class="rv-cur">now: ${cur} ${c.asset && ["sfx", "meme", "greenscreen", "music", "image"].includes(it.kind) ? `<button class="btn small rv-listen">▶ preview asset</button>` : ""}</div>
      ${chosen}
      <div class="rv-actions">
        ${it.kind === "added" ? "" : `<button class="btn small rv-keep ${st === "keep" ? "on" : ""}">✓ Keep</button>`}
        ${["sfx", "meme", "greenscreen", "music", "image", "added"].includes(it.kind) ? `<button class="btn small rv-change">✎ Swap…</button>` : ""}
        ${it.kind === "motion" || it.kind === "text" ? `<button class="btn small rv-edit">✎ Edit…</button>` : ""}
        <button class="btn small danger rv-remove ${st === "remove" ? "on" : ""}">✕ ${it.kind === "scene" ? "Cut this scene" : "Remove"}</button>
        <input class="rv-comment" placeholder="Comment (why / what you'd rather see)…" value="${esc(d.comment || "")}"></div>
      <div class="rv-opts" hidden></div></div>`;
  }
  const cssId = (k) => k.replace(/[^a-zA-Z0-9]/g, "_");
  function renderList() {
    const vis = items.filter((i) => F.kinds.includes(i.kind) && (!F.undecided || !statusOf(i)));
    $("#rvList").innerHTML = vis.length ? vis.map(cardHtml).join("") : `<div class="empty">Nothing to show with these filters.</div>`;
    $$("#rvList .rv-card").forEach(wireCard);
    refresh();
  }
  const itemOf = (key) => items.find((i) => i.key === key);
  async function save(key, status, choice, comment) {
    const d = await api(`/api/projects/${S}/review/decision`, { method: "POST", body: { key, status, choice: choice || null, comment: comment ?? "" } });
    dec.items[key] = d;
    const it = itemOf(key), el = $("#c-" + cssId(key));
    if (el) { el.outerHTML = cardHtml(it); wireCard($("#c-" + cssId(key))); }
    drawTl(drawTl._pps);
    refresh();
  }
  function wireCard(el) {
    const key = el.dataset.key, it = itemOf(key);
    const comment = () => $(".rv-comment", el).value;
    $(".rv-time", el).onclick = () => seek(it.start - 1.5, true, it.end + 1.0);
    $(".rv-keep", el)?.addEventListener("click", () => save(key, "keep", null, comment()));
    $(".rv-remove", el).addEventListener("click", () => save(key, "remove", null, comment()));
    $(".rv-comment", el).addEventListener("change", () => save(key, statusOf(it) || "comment", (dec.items[key] || {}).choice, comment()));
    $(".rv-listen", el)?.addEventListener("click", async (e) => {
      const a = await api("/api/assets/" + encodeURIComponent(it.current.asset)).catch(() => null);
      if (a) playAssetBtn(a, e.target);
    });
    $(".rv-change", el)?.addEventListener("click", () => openOptions(el, it));
    $(".rv-edit", el)?.addEventListener("click", () => openEdit(el, it));
  }
  function openCard(key) {
    const it = itemOf(key);
    if (!it) return;
    if (!F.kinds.includes(it.kind)) { F.kinds.push(it.kind); store.set("rvfilter:" + slug, F); $$("#rvKinds .rchip").forEach((c) => c.classList.toggle("on", F.kinds.includes(c.dataset.k))); renderList(); }
    const el = $("#c-" + cssId(key));
    if (el) { el.scrollIntoView({ behavior: "smooth", block: "center" }); el.classList.add("flash"); setTimeout(() => el.classList.remove("flash"), 1600); }
  }
  function playAssetBtn(a, btn) {
    const p = $("#player");
    if (!p.paused && p.dataset.id === a.id) { p.pause(); btn.textContent = "▶ preview asset"; return; }
    p.src = packUrl(a.path, a.root); p.dataset.id = a.id; p.currentTime = 0;
    p.play().then(() => (btn.textContent = "❚❚ stop")).catch(() => toast("Can't play this in the browser", true));
    p.onended = () => (btn.textContent = "▶ preview asset");
  }
  const optCard = (a) => `<div class="rv-opt" data-id="${esc(a.id)}">
      <div class="rv-opt-th" ${a.thumb ? `style="background-image:url('${thumbUrl(a.thumb)}')"` : ""}>${a.kind === "audio" ? `<span class="wave">${a.category === "music" ? "♫" : "♪"}</span>` : ""}${a.duration_s ? `<span class="dur">${(+a.duration_s).toFixed(1)}s</span>` : ""}</div>
      <div class="rv-opt-t" title="${esc(a.description || "")}">${esc(a.title)}</div>
      <div class="row" style="gap:4px"><button class="btn small rv-opt-play">▶</button><button class="btn small primary rv-opt-use">Use this</button></div></div>`;
  async function openOptions(el, it) {
    const box = $(".rv-opts", el);
    if (!box.hidden) { box.hidden = true; return; }
    box.hidden = false;
    box.innerHTML = `<div class="muted" style="font-size:12px">Recommended for this moment${it.moments?.length ? ` (${it.moments.join(", ")})` : ""}:</div><div class="rv-opt-grid" id="og"></div>
      <div class="row" style="margin-top:6px"><input class="rv-q" type="search" placeholder="…or search any asset (e.g. sad violin, bruh, explosion)" style="flex:1"><button class="btn small rv-go">Search</button></div>`;
    const grid = $("#og", box);
    const fill = (list) => {
      grid.innerHTML = list.length ? list.map(optCard).join("") : `<div class="muted">No matches.</div>`;
      $$(".rv-opt", grid).forEach((o, i) => {
        const a = list[i];
        $(".rv-opt-play", o).onclick = (e) => playAssetBtn(a, e.target);
        $(".rv-opt-use", o).onclick = () => save(it.key, "change", { asset: a.id }, $(".rv-comment", el).value);
      });
    };
    const load = async (q) => {
      grid.innerHTML = `<div class="muted">Loading…</div>`;
      try {
        if (q) {
          const cats = { sfx: ["sfx_meme", "sfx_ui", "sfx_minecraft", "sfx_mlg", "sfx_laugh"], meme: ["meme_video"], greenscreen: ["green_screen"], music: ["music"], image: ["image", "brand_sticker"] }[it.kind] || [];
          const p = new URLSearchParams({ q, limit: 12 }); cats.forEach((c) => p.append("category", c)); ["clean", "mild"].forEach((r) => p.append("rating", r));
          fill((await api("/api/assets?" + p)).items);
        } else fill((await api(`/api/projects/${S}/review/options?key=${encodeURIComponent(it.key)}`)).options);
      } catch (e) { grid.innerHTML = `<div class="warn">${esc(e.message)}</div>`; }
    };
    $(".rv-go", box).onclick = () => load($(".rv-q", box).value.trim());
    $(".rv-q", box).addEventListener("keydown", (e) => { if (e.key === "Enter") load(e.target.value.trim()); });
    load("");
  }
  async function openEdit(el, it) {
    const box = $(".rv-opts", el);
    if (!box.hidden) { box.hidden = true; return; }
    box.hidden = false;
    const c = it.current || {};
    if (it.kind === "text") {
      box.innerHTML = `<div class="row"><input class="rv-txt" style="flex:1" value="${esc(c.text || "")}"><select class="rv-sty">${["impact", "minecraft", "label", "danger", "retro", "gta"].map((s) => `<option ${s === c.style ? "selected" : ""}>${s}</option>`).join("")}</select><button class="btn small primary rv-sv">Save</button></div>`;
      $(".rv-sv", box).onclick = () => save(it.key, "change", { text: $(".rv-txt", box).value, style: $(".rv-sty", box).value }, $(".rv-comment", el).value);
    } else {
      const tpls = (await api("/api/motion").catch(() => ({ templates: [] }))).templates;
      const vars = { ...(c.vars || {}) };
      box.innerHTML = `<div class="row"><span class="muted">Graphic</span><select class="rv-tpl">${tpls.map((t) => `<option ${t.name === c.template ? "selected" : ""}>${esc(t.name)}</option>`).join("")}</select></div>
        <div class="rv-vars">${Object.entries(vars).map(([k, v]) => `<label class="field" style="margin-top:4px">${esc(k)}<input data-var="${esc(k)}" value="${esc(typeof v === "object" ? JSON.stringify(v) : v)}"></label>`).join("") || `<div class="faint">(uses the template's defaults)</div>`}</div>
        <div class="row" style="margin-top:6px"><button class="btn small primary rv-sv">Save</button></div>`;
      $(".rv-sv", box).onclick = () => {
        const nv = {}; $$("[data-var]", box).forEach((i) => (nv[i.dataset.var] = i.value));
        save(it.key, "change", { template: $(".rv-tpl", box).value, vars: nv }, $(".rv-comment", el).value);
      };
    }
  }

  // ------------------------------------------------------------- side panel actions
  $("#rvKinds").onclick = (e) => {
    const k = e.target.closest(".rchip")?.dataset.k; if (!k) return;
    const i = F.kinds.indexOf(k); i >= 0 ? F.kinds.splice(i, 1) : F.kinds.push(k);
    store.set("rvfilter:" + slug, F); e.target.closest(".rchip").classList.toggle("on"); renderList();
  };
  $("#rvUnd").onclick = (e) => { F.undecided = !F.undecided; e.target.classList.toggle("on"); store.set("rvfilter:" + slug, F); renderList(); };
  $("#rvGeneral").addEventListener("change", (e) => api(`/api/projects/${S}/review/general`, { method: "POST", body: { note: e.target.value } }).then(() => toast("Saved")));
  $("#rvMd").onclick = async () => {
    const r = await api(`/api/projects/${S}/review/md`);
    $("#rvModal").innerHTML = `<div class="modal" style="display:flex"><div class="modal-box" style="max-width:900px"><div class="modal-head"><b>REVIEW.md</b><span class="spacer"></span><button class="btn small" id="mmClose">✕</button></div><pre style="padding:14px;max-height:70vh;overflow:auto;white-space:pre-wrap">${esc(r.markdown)}</pre></div></div>`;
    $("#mmClose").onclick = () => ($("#rvModal").innerHTML = "");
  };
  $("#rvApply").onclick = async () => {
    let j;
    try { j = await api(`/api/projects/${S}/review/apply`, { method: "POST", body: {} }); } catch (e) { return toast(e.message, true); }
    $("#rvApply").disabled = true;
    const tick = async () => {
      const r = await api("/api/jobs/" + j.id).catch(() => null); if (!r) return;
      const el = $("#rvJob"); if (!el) { clearInterval(iv); return; }
      el.textContent = `${r.status} · ${r.elapsed}s\n` + r.log.slice(-4).join("\n");
      if (r.status !== "running") {
        clearInterval(iv); toast(r.status === "done" ? "New preview ready" : "Rebuild " + r.status, r.status !== "done");
        $("#rvApply").disabled = false; if (r.status === "done") setTimeout(() => ReviewPage(H, slug), 400);
      }
    };
    const iv = setInterval(tick, 2000); pollers.push(iv); tick();
  };
  $("#rvAddOpen").onclick = () => openAdd();
  function openAdd() {
    const t = vid ? vid.currentTime : 0;
    $("#rvModal").innerHTML = `<div class="modal" style="display:flex"><div class="modal-box" style="max-width:760px"><div class="modal-head"><b>Add something at ${fmt(t)}</b><span class="spacer"></span><button class="btn small" id="mmClose">✕</button></div>
      <div style="padding:14px;display:grid;gap:10px">
        <div class="seg">${[["sfx", "Sound effect"], ["meme", "Meme clip"], ["greenscreen", "Green screen"], ["motion", "Motion graphic"], ["text", "Text"]].map(([k, l], i) => `<button class="btn ${i ? "" : "on"}" data-ak="${k}">${l}</button>`).join("")}</div>
        <div id="addBody"></div></div></div></div>`;
    $("#mmClose").onclick = () => ($("#rvModal").innerHTML = "");
    let kind = "sfx";
    const body = async () => {
      const b = $("#addBody");
      if (kind === "text") {
        b.innerHTML = `<div class="row"><input id="addTxt" style="flex:1" placeholder="Text to show"><select id="addSty">${["impact", "minecraft", "label", "danger", "retro", "gta"].map((s) => `<option>${s}</option>`).join("")}</select></div><input id="addCm" placeholder="Why? (comment)" style="width:100%;margin-top:6px"><button class="btn primary" id="addGo" style="margin-top:6px">Add text</button>`;
        $("#addGo").onclick = async () => { await api(`/api/projects/${S}/review/add`, { method: "POST", body: { kind: "text", out_time: t, text: $("#addTxt").value, style: $("#addSty").value, comment: $("#addCm").value, label: $("#addTxt").value } }); toast("Added (press Apply to see it)"); $("#rvModal").innerHTML = ""; };
      } else if (kind === "motion") {
        const tpls = (await api("/api/motion")).templates;
        b.innerHTML = `<div class="row"><select id="addTpl">${tpls.map((x) => `<option>${esc(x.name)}</option>`).join("")}</select><input id="addTxt" style="flex:1" placeholder="Main text (title / label / text var)"></div><input id="addCm" placeholder="Why? (comment)" style="width:100%;margin-top:6px"><button class="btn primary" id="addGo" style="margin-top:6px">Add graphic</button>`;
        $("#addGo").onclick = async () => { const tx = $("#addTxt").value; await api(`/api/projects/${S}/review/add`, { method: "POST", body: { kind: "motion", out_time: t, template: $("#addTpl").value, vars: tx ? { text: tx, title: tx, label: tx } : {}, comment: $("#addCm").value, label: $("#addTpl").value } }); toast("Added (press Apply to see it)"); $("#rvModal").innerHTML = ""; };
      } else {
        b.innerHTML = `<div class="row"><input id="addQ" type="search" style="flex:1" placeholder="Search ${kind === "sfx" ? "sounds" : kind === "meme" ? "memes" : "green screens"}…"><button class="btn" id="addSearch">Search</button></div><div class="rv-opt-grid" id="addGrid" style="margin-top:8px"></div><input id="addCm" placeholder="Why? (comment)" style="width:100%;margin-top:6px">`;
        const cats = { sfx: ["sfx_meme", "sfx_ui", "sfx_minecraft", "sfx_mlg", "sfx_laugh"], meme: ["meme_video"], greenscreen: ["green_screen"] }[kind];
        const go = async () => {
          const p = new URLSearchParams({ q: $("#addQ").value, limit: 18 }); cats.forEach((c) => p.append("category", c)); ["clean", "mild"].forEach((r) => p.append("rating", r));
          const list = (await api("/api/assets?" + p)).items;
          $("#addGrid").innerHTML = list.map(optCard).join("") || `<div class="muted">No matches</div>`;
          $$("#addGrid .rv-opt").forEach((o, i) => {
            $(".rv-opt-play", o).onclick = (e) => playAssetBtn(list[i], e.target);
            $(".rv-opt-use", o).onclick = async () => { await api(`/api/projects/${S}/review/add`, { method: "POST", body: { kind, out_time: t, asset: list[i].id, comment: $("#addCm").value } }); toast("Added (press Apply to see it)"); $("#rvModal").innerHTML = ""; };
          });
        };
        $("#addSearch").onclick = go; $("#addQ").addEventListener("keydown", (e) => { if (e.key === "Enter") go(); });
        go();
      }
    };
    $$("[data-ak]").forEach((bt) => (bt.onclick = () => { $$("[data-ak]").forEach((x) => x.classList.remove("on")); bt.classList.add("on"); kind = bt.dataset.ak; body(); }));
    body();
  }

  renderList();
}

