.rv-top { display: grid; grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr); gap: 16px; align-items: start; position: sticky; top: 0; z-index: 20; background: var(--bg, #14161a); padding-bottom: 8px; }
@media (max-width: 1100px) { .rv-top { grid-template-columns: 1fr; position: static; } }
