.rv-card.st-keep { border-left-color: var(--grass); } .rv-card.st-change { border-left-color: var(--gold); }
.rv-card.st-remove { border-left-color: #c24; opacity: .75; } .rv-card.st-comment { border-left-color: #6f86d8; }
.rv-card.flash { box-shadow: 0 0 0 2px var(--gold); }
.rv-head { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.rv-time { cursor: pointer; color: var(--gold); font-family: monospace; font-size: 12px; }
.rv-kind { font-size: 11px; padding: 1px 8px; border-radius: 99px; border: 1px solid; text-transform: uppercase; letter-spacing: .04em; }
.rv-st { font-size: 12px; color: var(--muted); }
.rv-ctx { color: var(--muted); font-size: 12px; margin: 4px 0; font-style: italic; }
.rv-cur { font-size: 12px; margin: 4px 0; display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.rv-chosen { font-size: 12px; color: #ffe9a8; margin-bottom: 4px; }
.rv-actions { display: flex; gap: 6px; flex-wrap: wrap; align-items: center; }
.rv-actions .on { background: rgba(95,191,58,.25); border-color: var(--grass); }
.rv-comment { flex: 1; min-width: 220px; }
.rv-opt-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 8px; margin-top: 6px; }
.rv-opt { background: var(--panel-2); border: 1px solid var(--line); border-radius: 8px; padding: 6px; display: grid; gap: 4px; }
.rv-opt-th { height: 70px; background: #1b1e22 center/cover; border-radius: 6px; position: relative; display: flex; align-items: center; justify-content: center; }
.rv-opt-th .wave { font-size: 26px; opacity: .6; } .rv-opt-th .dur { position: absolute; right: 4px; bottom: 3px; font-size: 10px; background: #000a; padding: 0 4px; border-radius: 3px; }
.rv-opt-t { font-size: 12px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rv-opts { margin-top: 8px; padding-top: 8px; border-top: 1px dashed var(--line); }
.tl-item.st-keep { outline: 2px solid var(--grass); } .tl-item.st-change { outline: 2px solid var(--gold); } .tl-item.st-remove { opacity: .35; text-decoration: line-through; }
.tl-item.ti-scenes { background: #2d4a24; border-color: #6fbf4f; }
EOF
