WIPES = {"act2": "crodie_wipe", "act3": "pixel_wipe", "ham": "block_break_wipe", "tnt": "block_break_wipe",
         "end": "pixel_wipe", "speed": "block_break_wipe", "mobs": "block_break_wipe"}
CUT_AT = {"crodie_wipe": 0.55, "pixel_wipe": 0.42, "block_break_wipe": 0.42}
CHAPTERS = {"act2": ("CHAPTER 2", "THE RESET"), "act3": ("CHAPTER 3", "THE NEXT DAY")}
TIMECARDS = {"ham": "20 MINUTES LATER", "tnt": "500 BLOCKS LATER", "speed": "THE GRIND BEGINS", "mobs": "MOB FARMING TIME",
             "grass": "THE CHEAT CODE"}


def post_layers(edl: dict, info: dict, words: list) -> None:
    segs = edl["segments"]
    main = [s for s in segs if not s["id"].startswith("cold") and s["type"] == "source"]

    def seg_at(t):
        return next((s for s in main if s["in"] - 0.01 <= t <= s["out"] + 0.01), None)

    def word_time(a, b, phrase):
        for w in words:
            if a <= w["start"] <= b and phrase in w["word"].lower():
                return w["start"]
        return None

    win_first, win_last, wins = info["win_first"], info["win_last"], info["wins"]
    by_tag = {}
    for wid, w in wins.items():
        if w.get("tag"):
            by_tag.setdefault(w["tag"], wid)

    first = next(sg for sg in segs if not sg['id'].startswith('cold'))

    miss = []
    # ---------------------------------------------------- sfx
    for e in M_SFX:
        e = dict(e)
        t = e.pop("_t")
        sg = seg_at(t)
        if not sg:
            miss.append(("sfx", e["asset"], round(t, 1)))
            continue
        edl["audio"]["sfx"].append({**e, "seg": sg["id"], "src_at": round(t, 3)})
    for kind, part, ts, ex in M_VIS:
        t = T(part, ts)
        sg = seg_at(t)
        if not sg:
            miss.append((kind, ex.get("asset") or ex.get("template") or ex.get("text"), round(t, 1)))
            continue
        if kind == "gs":
            edl["overlays"].append({"type": "greenscreen", "seg": sg["id"], "src_at": round(t, 3), **ex})
        elif kind == "mo":
            edl["overlays"].append({"type": "motion", "seg": sg["id"], "src_at": round(t, 3), **ex})
        else:
            edl["text"].append({"seg": sg["id"], "src_at": round(t, 3), **ex})

    # ---------------------------------------------------- context captions + chaos meter zoom
    for tag, phrase, text, ex in CONTEXT:
        wid = by_tag.get(tag)
        if not wid:
            continue
        w = wins[wid]
        t = word_time(w["a"], w["b"], phrase)
        sg = seg_at(t) if t else None
        if not sg:
            miss.append(("context", text, tag))
            continue
        edl["text"].append({"seg": sg["id"], "src_at": round(t, 3), "text": text, **ex})
        edl["captions"]["hide"].append({"seg": sg["id"], "src_at": round(t, 3), "dur": ex["dur"]})
    wid = by_tag.get(METER_ZOOM["tag"])
    if wid:
        w = wins[wid]
        t = word_time(w["a"], w["b"], METER_ZOOM["phrase"])
        sg = seg_at(t) if t else None
        if sg:
            sg["zoom"] = [{"src_at": round(t + 0.4, 3), "to": 2.3, "in": 0.4, "hold": 2.6, "out": 0.5, "focus": METER_ZOOM["focus"]}]
            sg["_kind"] = "special"

    # ---------------------------------------------------- memes (cutaways inserted after the segment at that time)
    for part, ts, aid in MEMES:
        t = T(part, ts)
        k = next((i for i, s in enumerate(segs) if s["type"] == "source" and not s["id"].startswith("cold")
                  and s["in"] - 0.01 <= t <= s["out"] + 0.01), None)
        a = A.get(aid)
        if k is None or a is None or k >= len(segs) - 2:
            miss.append(("meme", aid, round(t, 1)))
            continue
        lo = a.get("use_in") or 0.0
        hi = a.get("use_out") or a["duration_s"]
        hi = min(hi, lo + 3.0)
        segs.insert(k + 1, {"id": f"meme-{k}", "type": "cutaway", "asset": aid, "in": round(lo, 2), "out": round(hi, 2)})

    # ---------------------------------------------------- music beds
    runs: list[list] = []
    t = 0.0
    last_bed = "epic"
    for s in segs:
        bed = {"tense": "fun"}.get(s.get("_bed"), s.get("_bed")) or last_bed
        last_bed = bed
        d = seg_duration(s, lambda i: A.get(i))
        if runs and runs[-1][0] == bed:
            runs[-1][2] = t + d
        else:
            runs.append([bed, t, t + d])
        t += d
    merged: list[list] = []
    for r in runs:                                   # beds are rare: epic >= 8 s (montages), every other bed >= 40 s
        need = 8.0 if r[0] == "epic" else 20.0
        if merged and merged[-1][0] == r[0]:
            merged[-1][2] = r[2]
        elif merged and (r[2] - r[1]) < need:
            merged[-1][2] = r[2]
        else:
            merged.append(r)
    edl["audio"]["music"] = []
    for bed, a, z in merged:
        edl["audio"]["music"].append({"asset": BEDS[bed], "at": round(a, 2), "until": round(z + 0.0, 2), "in": 0.0,
                                      "volume_db": BED_DB[bed], "fade_in": 1.0, "fade_out": 1.4, "duck": True})

    # ---------------------------------------------------- Flashback cinematic shots (only real, QA-passed ones)
    plan_f = HERE / "cin_plan.json"
    placed = 0
    if plan_f.exists():
        plan = json.loads(plan_f.read_text())
        for sh in plan:
            f = HERE / "broll" / sh["file"]
            if not f.exists():
                continue
            wid = next((i for i, w in wins.items() if w["opts"].get("cinematic") == sh["key"]), None)
            if not wid or not win_first.get(wid):
                miss.append(("cinematic", sh["file"], sh["key"]))
                continue
            edl["overlays"].append({"type": "video", "file": f"broll/{sh['file']}", "placement": "fullscreen", "audio": False,
                                    "seg": win_first[wid], "rel": sh.get("rel", 1.0), "dur": sh["dur"], "cinematic": sh["file"]})
            placed += 1
    print(f"cinematic shots placed: {placed}")

    # ---------------------------------------------------- end card
    last_main = [s for s in segs if s["type"] == "source"][-1]
    last_main["freeze_end"] = 6.0
    edl["overlays"].append({"type": "motion", "template": "crodie_end_card", "vars": {}, "seg": last_main["id"],
                            "rel": round(last_main["out"] - last_main["in"], 2) + 0.6})
    for m in miss:
        print("  (dropped, not in kept footage):", m)

